import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { constants, promises as fs } from "node:fs";
import { dirname, join } from "node:path";

import AdmZip from "adm-zip";

import { delay } from "../../shared/node/async.js";
import { reportDesktopEdgeFailure } from "../desktop-edge-failures.js";

export const MANAGED_ONEPASSWORD_CLI_VERSION = "2.35.0";
export const ONEPASSWORD_CODESIGN_REQUIREMENT =
	'identifier "com.1password.op" and anchor apple generic and certificate leaf[subject.OU] = "2BUA8C4S2C"';
export const SAND_OP_LAUNCHER_IDENTIFIER_REQUIREMENT = 'identifier "sand-op-launcher"';
export const SAND_OP_LAUNCHER_CODESIGN_REQUIREMENT = `${SAND_OP_LAUNCHER_IDENTIFIER_REQUIREMENT} and anchor apple generic and certificate leaf[subject.OU] = "DCNK4UB866"`;
export const ONEPASSWORD_SYSTEM_CLI_PATHS = [
	"/opt/homebrew/bin/op",
	"/usr/local/bin/op",
	"/usr/bin/op",
] as const;

const MAX_ARCHIVE_BYTES = 64 * 1024 * 1024;
const MAX_EXECUTABLE_BYTES = 64 * 1024 * 1024;
const MAX_PROCESS_OUTPUT_BYTES = 16 * 1024;
const DOWNLOAD_TIMEOUT_MS = 60_000;
const VERIFY_TIMEOUT_MS = 15_000;
const VERSION_TIMEOUT_MS = 15_000;
const ALLOWED_ARCHIVE_CONTENT_TYPES = new Set([
	"application/zip",
	"application/octet-stream",
	"binary/octet-stream",
]);

// The inspection shapes are the dev-controls edge contract's 1Password half
// (the panel page renders them), so they live in the edge declaration; this
// re-export keeps the runtime's importers on their existing path.
export type {
	SandOnePasswordCliCandidate,
	SandOnePasswordCliInspection,
	SandOnePasswordCliReadyCandidate,
} from "../../shared/rpc/dev-controls.js";
import type {
	SandOnePasswordCliCandidate,
	SandOnePasswordCliInspection,
	SandOnePasswordCliReadyCandidate,
	SandOnePasswordCliSource,
} from "../../shared/rpc/dev-controls.js";

type CliSource = SandOnePasswordCliSource;

function isReadyCandidate(
	candidate: SandOnePasswordCliCandidate,
): candidate is SandOnePasswordCliReadyCandidate {
	return candidate.state === "ready";
}

interface ProcessResult {
	readonly stdout: string;
	readonly stderr: string;
}

interface ManagedInstallation {
	readonly path: string;
	readonly committed: boolean;
}

export type SandOnePasswordCliProcess = (
	file: string,
	args: readonly string[],
	options: {
		readonly signal: AbortSignal;
		readonly timeoutMs: number;
		readonly maxBufferBytes: number;
		readonly env?: Readonly<Record<string, string>>;
	},
) => Promise<ProcessResult>;

export type SandOnePasswordCliDownload = (url: string, signal: AbortSignal) => Promise<Uint8Array>;

export interface SandOnePasswordCliRuntimeOptions {
	readonly installRoot: string;
	readonly launcherPath: string;
	readonly platform?: NodeJS.Platform;
	readonly arch?: NodeJS.Architecture;
	readonly systemPaths?: readonly string[];
	readonly download?: SandOnePasswordCliDownload;
	readonly runProcess?: SandOnePasswordCliProcess;
	/**
	 * Production requires Anysphere's Developer ID. The explicit development
	 * mode accepts an ad-hoc signature for the checkout-built launcher.
	 */
	readonly launcherVerification?: "anysphere" | "development";
}

function defaultProcess(
	file: string,
	args: readonly string[],
	options: {
		readonly signal: AbortSignal;
		readonly timeoutMs: number;
		readonly maxBufferBytes: number;
		readonly env?: Readonly<Record<string, string>>;
	},
): Promise<ProcessResult> {
	return new Promise((resolve, reject) => {
		execFile(
			file,
			[...args],
			{
				signal: options.signal,
				timeout: options.timeoutMs,
				maxBuffer: options.maxBufferBytes,
				windowsHide: true,
				env: options.env == null ? process.env : { ...options.env },
			},
			(error, stdout, stderr) => {
				if (error != null) {
					reject(error);
					return;
				}
				resolve({ stdout: stdout.toString(), stderr: stderr.toString() });
			},
		);
	});
}

export class SandOnePasswordCliError extends Error {}

function strictOpEntry(archive: Uint8Array): Buffer {
	if (archive.byteLength === 0 || archive.byteLength > MAX_ARCHIVE_BYTES) {
		throw new SandOnePasswordCliError("The 1Password CLI archive size is invalid.");
	}
	let zip: AdmZip;
	try {
		zip = new AdmZip(Buffer.from(archive.buffer, archive.byteOffset, archive.byteLength));
	} catch {
		throw new SandOnePasswordCliError("The 1Password CLI archive is invalid.");
	}
	const entries = zip.getEntries();
	const names = new Set(entries.map((entry) => entry.entryName));
	if (entries.length !== 2 || !names.has("op") || !names.has("op.sig")) {
		throw new SandOnePasswordCliError("The 1Password CLI archive has unexpected entries.");
	}
	const entry = entries.find((candidate) => candidate.entryName === "op");
	const signature = entries.find((candidate) => candidate.entryName === "op.sig");
	if (
		entry == null ||
		entry.isDirectory ||
		entry.header.size <= 0 ||
		entry.header.size > MAX_EXECUTABLE_BYTES
	) {
		throw new SandOnePasswordCliError("The 1Password CLI archive does not contain a valid op.");
	}
	if (
		signature == null ||
		signature.isDirectory ||
		signature.header.size <= 0 ||
		signature.header.size > 4 * 1024
	) {
		throw new SandOnePasswordCliError("The 1Password CLI archive signature entry is invalid.");
	}
	// ZIP external mode 0120000 is a symlink. Zero means the archive omitted
	// Unix mode metadata, which the vendor archive and our synthetic tests allow.
	const unixMode = (entry.attr >>> 16) & 0xffff;
	const signatureMode = (signature.attr >>> 16) & 0xffff;
	if ((unixMode & 0o170000) === 0o120000 || (signatureMode & 0o170000) === 0o120000) {
		throw new SandOnePasswordCliError("The 1Password CLI archive entry cannot be a symlink.");
	}
	const executable = entry.getData();
	if (executable.byteLength !== entry.header.size || executable.byteLength > MAX_EXECUTABLE_BYTES) {
		throw new SandOnePasswordCliError("The 1Password CLI executable size is invalid.");
	}
	return executable;
}

function versionIsBounded(raw: string): string | null {
	const version = raw.trim();
	return /^2\.\d{1,3}\.\d{1,3}(?:[-+][0-9A-Za-z.-]{1,64})?$/.test(version) ? version : null;
}

export class SandOnePasswordCliRuntime {
	private readonly platform: NodeJS.Platform;
	private readonly arch: NodeJS.Architecture;
	private readonly systemPaths: readonly string[];
	private readonly download: SandOnePasswordCliDownload;
	private readonly runProcess: SandOnePasswordCliProcess;

	constructor(private readonly options: SandOnePasswordCliRuntimeOptions) {
		this.platform = options.platform ?? process.platform;
		this.arch = options.arch ?? process.arch;
		this.systemPaths = options.systemPaths ?? ONEPASSWORD_SYSTEM_CLI_PATHS;
		this.download = options.download ?? downloadFromOnePassword;
		this.runProcess = options.runProcess ?? defaultProcess;
	}

	async resolveVerifiedLauncherPath(signal: AbortSignal): Promise<string> {
		if (this.platform !== "darwin") {
			throw new SandOnePasswordCliError(
				"The secure 1Password launcher is supported on macOS only.",
			);
		}
		await fs.access(this.options.launcherPath, constants.X_OK);
		const resolvedPath = await fs.realpath(this.options.launcherPath);
		const requirement =
			this.options.launcherVerification === "development"
				? SAND_OP_LAUNCHER_IDENTIFIER_REQUIREMENT
				: SAND_OP_LAUNCHER_CODESIGN_REQUIREMENT;
		await this.runProcess(
			"/usr/bin/codesign",
			["--verify", "--strict", "--verbose=4", `-R=${requirement}`, resolvedPath],
			{
				signal,
				timeoutMs: VERIFY_TIMEOUT_MS,
				maxBufferBytes: MAX_PROCESS_OUTPUT_BYTES,
			},
		);
		return resolvedPath;
	}

	get managedPath(): string {
		return join(
			this.options.installRoot,
			`v${MANAGED_ONEPASSWORD_CLI_VERSION}`,
			this.artifactArch(),
			"op",
		);
	}

	async inspect(signal: AbortSignal): Promise<SandOnePasswordCliInspection> {
		if (this.platform !== "darwin") {
			return {
				platformSupported: false,
				selected: null,
				candidates: [],
				detail: "Managed 1Password CLI is supported on macOS only",
			};
		}
		const launcherPath = await this.resolveVerifiedLauncherPath(signal);
		const candidates = await Promise.all(
			[
				...this.systemPaths.map((path) => [path, "system"] as const),
				[this.managedPath, "managed"] as const,
			].map(
				async ([path, source]) => await this.inspectCandidate(path, source, launcherPath, signal),
			),
		);
		const readyCandidates = candidates.filter(isReadyCandidate);
		const selected =
			readyCandidates.find((candidate) => candidate.source === "system") ??
			readyCandidates.find((candidate) => candidate.source === "managed") ??
			null;
		return {
			platformSupported: true,
			selected,
			candidates,
			detail:
				selected != null
					? `${selected.source === "system" ? "System" : "Managed"} CLI ready`
					: "No verified 1Password CLI is ready",
		};
	}

	async prepareManaged(signal: AbortSignal): Promise<SandOnePasswordCliInspection> {
		const installation = await this.ensureManagedInstalled(signal);
		return await this.inspect(installation.committed ? new AbortController().signal : signal);
	}

	async resolveVerifiedPath(
		signal: AbortSignal,
		options: { readonly prepareManaged: boolean },
	): Promise<string> {
		const inspected = await this.inspect(signal);
		if (inspected.selected != null) return inspected.selected.path;
		if (!options.prepareManaged) {
			throw new SandOnePasswordCliError("No verified 1Password CLI is ready.");
		}
		return (await this.ensureManagedInstalled(signal)).path;
	}

	async verify(path: string, signal: AbortSignal): Promise<void> {
		if (this.platform !== "darwin") {
			throw new SandOnePasswordCliError("Managed 1Password CLI is supported on macOS only.");
		}
		const resolvedPath = await fs.realpath(path);
		await this.runProcess(
			"/usr/bin/codesign",
			[
				"--verify",
				"--strict",
				"--verbose=4",
				`-R=${ONEPASSWORD_CODESIGN_REQUIREMENT}`,
				resolvedPath,
			],
			{
				signal,
				timeoutMs: VERIFY_TIMEOUT_MS,
				maxBufferBytes: MAX_PROCESS_OUTPUT_BYTES,
			},
		);
	}

	private async inspectCandidate(
		path: string,
		source: CliSource,
		launcherPath: string,
		signal: AbortSignal,
	): Promise<SandOnePasswordCliCandidate> {
		try {
			await fs.access(path, constants.X_OK);
		} catch {
			return { source, path, state: "missing" };
		}
		try {
			const version = await this.readVersion({ path, launcherPath, signal });
			if (
				version == null ||
				(source === "managed" && version !== MANAGED_ONEPASSWORD_CLI_VERSION)
			) {
				return { source, path, state: "invalid" };
			}
			return { source, path, state: "ready", version, signature: "verified" };
		} catch (error) {
			if (signal.aborted) throw error;
			return { source, path, state: "invalid" };
		}
	}

	private async readVersion(options: {
		readonly path: string;
		readonly launcherPath: string;
		readonly signal: AbortSignal;
	}): Promise<string | null> {
		const resolvedPath = await fs.realpath(options.path);
		const result = await this.runProcess(options.launcherPath, [resolvedPath, "--version"], {
			signal: options.signal,
			timeoutMs: VERSION_TIMEOUT_MS,
			maxBufferBytes: MAX_PROCESS_OUTPUT_BYTES,
			env: scrubbedOnePasswordEnvironment(),
		});
		return versionIsBounded(result.stdout);
	}

	private async ensureManagedInstalled(signal: AbortSignal): Promise<ManagedInstallation> {
		const destination = this.managedPath;
		const launcherPath = await this.resolveVerifiedLauncherPath(signal);
		try {
			await fs.access(destination, constants.X_OK);
			await this.verify(destination, signal);
			const version = await this.readVersion({
				path: destination,
				launcherPath,
				signal,
			});
			if (version === MANAGED_ONEPASSWORD_CLI_VERSION) {
				return { path: destination, committed: false };
			}
		} catch (error) {
			if (signal.aborted) throw error;
		}

		const destinationDirectory = dirname(destination);
		await fs.mkdir(destinationDirectory, { recursive: true, mode: 0o700 });
		await fs.chmod(this.options.installRoot, 0o700);
		await fs.chmod(destinationDirectory, 0o700);

		const downloadController = new AbortController();
		const deadlineController = new AbortController();
		const downloadPromise = this.download(
			this.artifactUrl(this.artifactArch()),
			AbortSignal.any([signal, downloadController.signal]),
		);
		const downloadOutcomePromise = downloadPromise.then(
			(archive) => ({ kind: "download" as const, archive }),
			(error: unknown) => ({ kind: "error" as const, error }),
		);
		const deadlinePromise = delay(DOWNLOAD_TIMEOUT_MS, deadlineController.signal).then(() => ({
			kind: "timeout" as const,
		}));
		const outcome = await Promise.race([downloadOutcomePromise, deadlinePromise]).finally(() => {
			deadlineController.abort();
		});
		if (outcome.kind === "timeout") {
			const timeoutError = new DOMException("1Password CLI download timed out", "TimeoutError");
			downloadController.abort(timeoutError);
			throw timeoutError;
		}
		if (outcome.kind === "error") throw outcome.error;
		const archive = outcome.archive;
		const executable = strictOpEntry(archive);
		const temporaryPath = join(destinationDirectory, `.op-${process.pid}-${randomUUID()}`);
		try {
			const file = await fs.open(temporaryPath, "wx", 0o700);
			try {
				await file.writeFile(executable);
				await file.sync();
			} finally {
				await file.close();
			}
			await fs.chmod(temporaryPath, 0o700);
			await this.verify(temporaryPath, signal);
			const version = await this.readVersion({
				path: temporaryPath,
				launcherPath,
				signal,
			});
			if (version !== MANAGED_ONEPASSWORD_CLI_VERSION) {
				throw new SandOnePasswordCliError(
					`The managed 1Password CLI did not report version ${MANAGED_ONEPASSWORD_CLI_VERSION}.`,
				);
			}
			signal.throwIfAborted();
			await fs.rename(temporaryPath, destination);
			const committedSignal = new AbortController().signal;
			await fs.chmod(destination, 0o700);
			await this.verify(destination, committedSignal);
			return { path: destination, committed: true };
		} finally {
			await fs.rm(temporaryPath, { force: true });
		}
	}

	private artifactArch(): "arm64" | "amd64" {
		if (this.platform !== "darwin") {
			throw new SandOnePasswordCliError("Managed 1Password CLI is supported on macOS only.");
		}
		if (this.arch === "arm64") return "arm64";
		if (this.arch === "x64") return "amd64";
		throw new SandOnePasswordCliError("Unsupported macOS architecture.");
	}

	private artifactUrl(arch: "arm64" | "amd64"): string {
		return `https://cache.agilebits.com/dist/1P/op2/pkg/v${MANAGED_ONEPASSWORD_CLI_VERSION}/op_darwin_${arch}_v${MANAGED_ONEPASSWORD_CLI_VERSION}.zip`;
	}
}

export function scrubbedOnePasswordEnvironment(
	env: NodeJS.ProcessEnv = process.env,
): Record<string, string> {
	const scrubbed: Record<string, string> = {};
	for (const [key, value] of Object.entries(env)) {
		if (value == null) continue;
		if (key.startsWith("OP_")) continue;
		scrubbed[key] = value;
	}
	scrubbed.OP_CACHE = "false";
	scrubbed.OP_BIOMETRIC_UNLOCK_ENABLED = "true";
	scrubbed.OP_LOAD_DESKTOP_APP_SETTINGS = "false";
	return scrubbed;
}

export async function downloadFromOnePassword(
	rawUrl: string,
	signal: AbortSignal,
): Promise<Uint8Array> {
	const url = new URL(rawUrl);
	const expectedPaths = new Set([
		`/dist/1P/op2/pkg/v${MANAGED_ONEPASSWORD_CLI_VERSION}/op_darwin_arm64_v${MANAGED_ONEPASSWORD_CLI_VERSION}.zip`,
		`/dist/1P/op2/pkg/v${MANAGED_ONEPASSWORD_CLI_VERSION}/op_darwin_amd64_v${MANAGED_ONEPASSWORD_CLI_VERSION}.zip`,
	]);
	if (
		url.protocol !== "https:" ||
		url.hostname !== "cache.agilebits.com" ||
		url.port !== "" ||
		url.username !== "" ||
		url.password !== "" ||
		url.search !== "" ||
		url.hash !== "" ||
		!expectedPaths.has(url.pathname)
	) {
		throw new SandOnePasswordCliError("The 1Password CLI download URL is not vendor-owned.");
	}
	const response = await fetch(url, { redirect: "error", signal });
	if (!response.ok) {
		if (response.body != null) {
			await response.body
				.cancel()
				.catch((error) => reportDesktopEdgeFailure("onepassword", "body-cancel", error));
		}
		throw new SandOnePasswordCliError(
			`The 1Password CLI download failed with HTTP ${response.status}.`,
		);
	}
	const contentType = response.headers.get("content-type")?.split(";", 1)[0]?.trim().toLowerCase();
	if (contentType == null || !ALLOWED_ARCHIVE_CONTENT_TYPES.has(contentType)) {
		if (response.body != null) {
			await response.body
				.cancel()
				.catch((error) => reportDesktopEdgeFailure("onepassword", "body-cancel", error));
		}
		throw new SandOnePasswordCliError("The 1Password CLI download type could not be verified.");
	}
	const contentLength = response.headers.get("content-length");
	const length = contentLength == null ? Number.NaN : Number(contentLength);
	if (!Number.isSafeInteger(length) || length <= 0 || length > MAX_ARCHIVE_BYTES) {
		if (response.body != null) {
			await response.body
				.cancel()
				.catch((error) => reportDesktopEdgeFailure("onepassword", "body-cancel", error));
		}
		throw new SandOnePasswordCliError("The 1Password CLI download size could not be verified.");
	}
	if (response.body == null) {
		throw new SandOnePasswordCliError("The 1Password CLI download body was missing.");
	}
	const reader = response.body.getReader();
	const archive = new Uint8Array(length);
	let received = 0;
	for (;;) {
		const next = await reader.read();
		if (next.done) break;
		const nextReceived = received + next.value.byteLength;
		if (nextReceived > MAX_ARCHIVE_BYTES || nextReceived > length) {
			await reader.cancel();
			throw new SandOnePasswordCliError("The 1Password CLI download was unexpectedly large.");
		}
		archive.set(next.value, received);
		received = nextReceived;
	}
	if (received !== length) {
		throw new SandOnePasswordCliError("The 1Password CLI download size did not match.");
	}
	return archive;
}
