import type { SandOnePasswordCliInspection } from "./onepassword-cli-runtime.js";

export type OnePasswordProvisioningErrorCode =
	| "busy"
	| "cancelled"
	| "conflict"
	| "delivery-indeterminate"
	| "denied"
	| "integration-off"
	| "invalid-input"
	| "invalid-output"
	| "missing-cli"
	| "op-error"
	| "permission"
	| "sink-unavailable"
	| "timeout"
	| "unsupported-platform"
	| "unsupported-version";

export class OnePasswordProvisioningError extends Error {
	constructor(
		readonly code: OnePasswordProvisioningErrorCode,
		message: string,
	) {
		super(message);
		this.name = "OnePasswordProvisioningError";
	}
}

export interface OnePasswordAccount {
	readonly accountUuid: string;
	readonly email: string;
	readonly url: string;
}

export interface OnePasswordVault {
	readonly vaultId: string;
	readonly vaultName: string;
}

export type OnePasswordProvisioningReadiness =
	| { readonly state: "unsupported-platform" }
	| { readonly state: "missing-cli" }
	| { readonly state: "unsupported-version"; readonly version: string }
	| {
			readonly state: "ready";
			readonly source: "system" | "managed";
			readonly path: string;
			readonly version: string;
	  };

export interface OnePasswordProvisioningSinkRequest {
	readonly accountUuid: string;
	readonly accountUrl: string;
	readonly vaultId: string;
	readonly vaultName: string;
	readonly serviceAccountName: string;
	readonly expiresInSeconds: number;
	/**
	 * Secret-bearing field. A sink must consume it synchronously within this
	 * Electron-main call and must not log, persist locally, or forward it to
	 * renderer IPC.
	 */
	readonly token: string;
}

export interface OnePasswordProvisioningSinkReceipt {
	readonly consumerReference: string;
}

export type OnePasswordProvisioningSink =
	| {
			readonly availability: "unavailable";
			/**
			 * After 1Password mints a token, a rejected or timed-out delivery is
			 * indeterminate and blocks further mutations on that bridge instance.
			 * A production sink must reconcile that state before replacing it.
			 */
			accept(
				request: OnePasswordProvisioningSinkRequest,
				signal: AbortSignal,
			): Promise<OnePasswordProvisioningSinkReceipt>;
	  }
	| {
			readonly availability: "available";
			/**
			 * After 1Password mints a token, a rejected or timed-out delivery is
			 * indeterminate and blocks further mutations on that bridge instance.
			 * A production sink must reconcile that state before replacing it.
			 */
			accept(
				request: OnePasswordProvisioningSinkRequest,
				signal: AbortSignal,
			): Promise<OnePasswordProvisioningSinkReceipt>;
	  };

export const unavailableOnePasswordProvisioningSink: OnePasswordProvisioningSink = {
	availability: "unavailable",
	async accept(): Promise<never> {
		throw new OnePasswordProvisioningError(
			"sink-unavailable",
			"1Password provisioning is unavailable until a credential consumer is configured.",
		);
	},
};

export interface OnePasswordOpResult {
	readonly stdout: string;
	readonly stderr: string;
}

export type OnePasswordOpExecutor = (
	file: string,
	args: readonly string[],
	options: {
		readonly signal: AbortSignal;
		readonly timeoutMs: number;
		readonly maxBufferBytes: number;
		readonly env: Readonly<Record<string, string>>;
	},
) => Promise<OnePasswordOpResult>;

export interface OnePasswordCliRuntime {
	inspect(signal: AbortSignal): Promise<SandOnePasswordCliInspection>;
	prepareManaged(signal: AbortSignal): Promise<SandOnePasswordCliInspection>;
	resolveVerifiedLauncherPath(signal: AbortSignal): Promise<string>;
}

export interface OnePasswordDesktopProvisioningBridgeOptions {
	readonly runtime: OnePasswordCliRuntime;
	readonly sink?: OnePasswordProvisioningSink;
	readonly executor?: OnePasswordOpExecutor;
	readonly prepareManagedCli?: boolean;
}
