import path from "node:path";

import { getSandRootDir } from "../../host/host-paths.js";
import { invariant } from "../../shared/invariant.js";
import type {
	SandDevOnePasswordCheckResult,
	SandDevOnePasswordCliStatus,
	SandOnePasswordCliInspection,
} from "../../shared/rpc/dev-controls.js";
import { SandOnePasswordCliRuntime } from "./onepassword-cli-runtime.js";
import {
	OnePasswordDesktopProvisioningBridge,
	OnePasswordProvisioningError,
	unavailableOnePasswordProvisioningSink,
	type OnePasswordOpExecutor,
	type OnePasswordProvisioningSink,
} from "./onepassword-provisioning-bridge.js";

// The panel-facing result shapes are the dev-controls edge contract's 1Password
// half; the re-export keeps this controller's importers on their existing path.
export type {
	SandDevOnePasswordCheckResult,
	SandDevOnePasswordCliStatus,
} from "../../shared/rpc/dev-controls.js";

const DEFAULT_VAULT_NAME = "Shared with Sand";
const SYNTHETIC_TOKEN = "ops_SYNTHETIC_DEV_ONLY_TOKEN_DO_NOT_USE";

function unavailable(detail: string): SandDevOnePasswordCliStatus {
	return {
		platformSupported: process.platform === "darwin",
		selected: null,
		candidates: [],
		detail,
	};
}

function isAbortError(error: unknown): boolean {
	if (error instanceof DOMException) return error.name === "AbortError";
	if (!(error instanceof Error)) return false;
	return error.name === "AbortError" || ("code" in error && error.code === "ABORT_ERR");
}

function failedCheck(
	action: SandDevOnePasswordCheckResult["action"],
	error: unknown,
): SandDevOnePasswordCheckResult {
	const code = error instanceof OnePasswordProvisioningError ? ` (${error.code})` : "";
	return {
		isOk: false,
		action,
		summary: `1Password ${action} check failed safely${code}`,
		accountCount: 0,
		vaultCount: 0,
		foundDefaultVault: false,
	};
}

export async function runSyntheticOnePasswordProvisioningExercise(): Promise<SandDevOnePasswordCheckResult> {
	let vaultCreated = false;
	let sinkAccepted = false;
	let environmentWasScrubbed = true;
	const runtime = {
		async inspect(): Promise<SandOnePasswordCliInspection> {
			return {
				platformSupported: true,
				selected: {
					source: "managed",
					path: "/synthetic/op",
					version: "2.35.0",
					state: "ready",
					signature: "verified",
				},
				candidates: [],
				detail: "Synthetic CLI ready",
			};
		},
		async prepareManaged(): Promise<SandOnePasswordCliInspection> {
			return await this.inspect();
		},
		async resolveVerifiedLauncherPath(): Promise<string> {
			return "/synthetic/sand-op-launcher";
		},
	};
	const executor: OnePasswordOpExecutor = async (_file, args, options) => {
		environmentWasScrubbed &&=
			options.env.OP_SERVICE_ACCOUNT_TOKEN == null &&
			!Object.keys(options.env).some(
				(key) => key.startsWith("OP_SESSION") || key.startsWith("OP_CONNECT"),
			);
		const command = args.slice(1);
		if (command[0] === "account") {
			return {
				stdout: JSON.stringify([
					{
						account_uuid: "synthetic-account",
						email: "synthetic@example.invalid",
						url: "https://synthetic.1password.example",
					},
				]),
				stderr: "",
			};
		}
		if (command[0] === "vault" && command[1] === "list") {
			return {
				stdout: vaultCreated
					? JSON.stringify([{ id: "synthetic-vault", name: DEFAULT_VAULT_NAME }])
					: "[]",
				stderr: "",
			};
		}
		if (command[0] === "vault" && command[1] === "create") {
			vaultCreated = true;
			return {
				stdout: JSON.stringify({
					id: "synthetic-vault",
					name: DEFAULT_VAULT_NAME,
				}),
				stderr: "",
			};
		}
		if (command[0] === "service-account") {
			return { stdout: SYNTHETIC_TOKEN, stderr: "" };
		}
		invariant(false, "Unexpected synthetic 1Password command.");
	};
	const sink: OnePasswordProvisioningSink = {
		availability: "available",
		async accept(request) {
			sinkAccepted = request.token === SYNTHETIC_TOKEN;
			return { consumerReference: "synthetic-receipt" };
		},
	};
	try {
		const bridge = new OnePasswordDesktopProvisioningBridge({
			runtime,
			executor,
			sink,
			prepareManagedCli: false,
		});
		const signal = new AbortController().signal;
		const accounts = await bridge.listAccounts(signal);
		const existing = await bridge.findVault(
			{
				accountUuid: accounts[0]?.accountUuid ?? "",
				vaultName: DEFAULT_VAULT_NAME,
			},
			signal,
		);
		const vault =
			existing ??
			(await bridge.createVault(
				{
					accountUuid: accounts[0]?.accountUuid ?? "",
					vaultName: DEFAULT_VAULT_NAME,
				},
				signal,
			));
		const receipt = await bridge.mintAndDeliver(
			{
				accountUuid: accounts[0]?.accountUuid ?? "",
				vaultId: vault.vaultId,
				serviceAccountName: "Sand synthetic service account",
				expiresInSeconds: 3_600,
			},
			signal,
		);
		const publicResult = {
			accountCount: accounts.length,
			vaultCount: 1,
			foundDefaultVault: existing != null,
			consumerReference: receipt.consumerReference,
		};
		const tokenContained = !JSON.stringify(publicResult).includes(SYNTHETIC_TOKEN);
		return {
			isOk: sinkAccepted && environmentWasScrubbed && tokenContained,
			action: "synthetic-provisioning",
			summary:
				sinkAccepted && environmentWasScrubbed && tokenContained
					? "Synthetic provisioning completed with token containment"
					: "Synthetic provisioning containment check failed",
			accountCount: publicResult.accountCount,
			vaultCount: publicResult.vaultCount,
			foundDefaultVault: publicResult.foundDefaultVault,
		};
	} catch (error) {
		return failedCheck("synthetic-provisioning", error);
	}
}

export function createOnePasswordCliDevController(options: { readonly projectDir: string }): {
	inspect(): Promise<SandDevOnePasswordCliStatus>;
	prepare(): Promise<SandDevOnePasswordCliStatus>;
	cancel(): void;
	listAccounts(): Promise<SandDevOnePasswordCheckResult>;
	listVaults(): Promise<SandDevOnePasswordCheckResult>;
	findDefaultVault(): Promise<SandDevOnePasswordCheckResult>;
	runSyntheticProvisioning(): Promise<SandDevOnePasswordCheckResult>;
} {
	let runtime: SandOnePasswordCliRuntime | undefined;
	let readBridge: OnePasswordDesktopProvisioningBridge | undefined;
	let prepareController: AbortController | undefined;
	const getRuntime = (): SandOnePasswordCliRuntime => {
		return (runtime ??= new SandOnePasswordCliRuntime({
			installRoot: path.join(getSandRootDir(), "onepassword-cli"),
			launcherPath: path.join(options.projectDir, "dist", "native", "sand-op-launcher"),
			launcherVerification: "development",
		}));
	};
	const getReadBridge = (): OnePasswordDesktopProvisioningBridge => {
		return (readBridge ??= new OnePasswordDesktopProvisioningBridge({
			runtime: getRuntime(),
			sink: unavailableOnePasswordProvisioningSink,
			prepareManagedCli: false,
		}));
	};
	return {
		async inspect(): Promise<SandDevOnePasswordCliStatus> {
			try {
				return await getRuntime().inspect(new AbortController().signal);
			} catch {
				return unavailable("1Password CLI inspection failed safely");
			}
		},
		async prepare(): Promise<SandDevOnePasswordCliStatus> {
			if (prepareController != null) {
				return unavailable("Managed 1Password CLI preparation is already running");
			}
			const controller = new AbortController();
			prepareController = controller;
			try {
				return await getRuntime().prepareManaged(controller.signal);
			} catch (error) {
				return unavailable(
					isAbortError(error)
						? "Managed 1Password CLI preparation canceled"
						: "Managed 1Password CLI preparation failed safely",
				);
			} finally {
				if (prepareController === controller) prepareController = undefined;
			}
		},
		cancel(): void {
			prepareController?.abort();
		},
		async listAccounts(): Promise<SandDevOnePasswordCheckResult> {
			try {
				const accounts = await getReadBridge().listAccounts(new AbortController().signal);
				return {
					isOk: true,
					action: "accounts",
					summary: `${accounts.length} 1Password account${accounts.length === 1 ? "" : "s"} available`,
					accountCount: accounts.length,
					vaultCount: 0,
					foundDefaultVault: false,
				};
			} catch (error) {
				return failedCheck("accounts", error);
			}
		},
		async listVaults(): Promise<SandDevOnePasswordCheckResult> {
			try {
				const signal = new AbortController().signal;
				const accounts = await getReadBridge().listAccounts(signal);
				const first = accounts[0];
				if (first == null) {
					return {
						isOk: true,
						action: "vaults",
						summary: "No 1Password account is available",
						accountCount: 0,
						vaultCount: 0,
						foundDefaultVault: false,
					};
				}
				const vaults = await getReadBridge().listVaults({ accountUuid: first.accountUuid }, signal);
				return {
					isOk: true,
					action: "vaults",
					summary: `${vaults.length} vault${vaults.length === 1 ? "" : "s"} available for the first account`,
					accountCount: accounts.length,
					vaultCount: vaults.length,
					foundDefaultVault: vaults.some((vault) => vault.vaultName === DEFAULT_VAULT_NAME),
				};
			} catch (error) {
				return failedCheck("vaults", error);
			}
		},
		async findDefaultVault(): Promise<SandDevOnePasswordCheckResult> {
			try {
				const signal = new AbortController().signal;
				const accounts = await getReadBridge().listAccounts(signal);
				const first = accounts[0];
				if (first == null) {
					return {
						isOk: true,
						action: "find-vault",
						summary: "No 1Password account is available",
						accountCount: 0,
						vaultCount: 0,
						foundDefaultVault: false,
					};
				}
				const found = await getReadBridge().findVault(
					{
						accountUuid: first.accountUuid,
						vaultName: DEFAULT_VAULT_NAME,
					},
					signal,
				);
				return {
					isOk: true,
					action: "find-vault",
					summary:
						found == null
							? "The default Sand vault was not found"
							: "The default Sand vault is available",
					accountCount: accounts.length,
					vaultCount: found == null ? 0 : 1,
					foundDefaultVault: found != null,
				};
			} catch (error) {
				return failedCheck("find-vault", error);
			}
		},
		async runSyntheticProvisioning(): Promise<SandDevOnePasswordCheckResult> {
			return await runSyntheticOnePasswordProvisioningExercise();
		},
	};
}
