export { isDevControlsEnabled };

const DEFAULT_CONTAINER_NAME = "sand-dev-box";
const DEFAULT_GATEWAY_URL = "http://127.0.0.1:1340";
// The box always publishes noVNC on this port (dev-box-docker.mjs `-p 6080:6080`),
// independent of the gateway's host port, so the desktop URL pins it.
const NOVNC_PORT = 6080;
const GATEWAY_PROBE_TIMEOUT_MS = 2_000;
const LOG_TAIL_LINES = 200;
let devControlsWindow: BrowserWindow | undefined;

function sandProjectDir(): string {
	// dist/electron-main/main.cjs (this bundle) -> the checkout's sand/ root two levels up.
	return path.resolve(__dirname, "..", "..");
}

const onePasswordCliDevController = createOnePasswordCliDevController({
	projectDir: sandProjectDir(),
});

function devBoxScriptPath(): string {
	return path.join(sandProjectDir(), "scripts", "dev-box-docker.mjs");
}

function containerName(): string {
	return process.env.SAND_DEV_BOX_CONTAINER ?? DEFAULT_CONTAINER_NAME;
}

function gatewayUrl(): string {
	const fromEnv = process.env.SAND_HOST_GATEWAY_URL?.trim();
	return fromEnv != null && fromEnv.length > 0 ? fromEnv : DEFAULT_GATEWAY_URL;
}

async function execCapture(
	command: string,
	args: readonly string[],
	options: { readonly env?: NodeJS.ProcessEnv } = {},
): Promise<SandDevCommandResult> {
	const startedAt = Date.now();
	return await new Promise<SandDevCommandResult>((resolve) => {
		const child = spawn(command, [...args], {
			cwd: sandProjectDir(),
			env: options.env ?? process.env,
			stdio: ["ignore", "pipe", "pipe"],
		});
		let output = "";
		const append = (chunk: Buffer): void => {
			output += chunk.toString();
			// Cap retained output so a chatty rebuild can never balloon memory; the
			// panel only ever shows a tail.
			if (output.length > 200_000) {
				output = output.slice(output.length - 200_000);
			}
		};
		child.stdout?.on("data", append);
		child.stderr?.on("data", append);
		child.on("error", (error) => {
			resolve({
				isOk: false,
				exitCode: null,
				output: `${output}\n${String(error)}`.trim(),
				durationMs: Date.now() - startedAt,
			});
		});
		child.on("close", (code) => {
			resolve({
				isOk: code === 0,
				exitCode: code,
				output: output.trim(),
				durationMs: Date.now() - startedAt,
			});
		});
	});
}

function devScriptEnv(): NodeJS.ProcessEnv {
	// The dev scripts are ESM Node scripts; the desktop runs under Electron, so
	// re-enter our own binary as a plain Node runtime to execute them.
	return { ...process.env, ELECTRON_RUN_AS_NODE: "1" };
}

async function runDevBoxScript(
	subcommand: SandDevBoxScriptCommand,
	extraEnv: NodeJS.ProcessEnv = {},
): Promise<SandDevCommandResult> {
	return await execCapture(process.execPath, [devBoxScriptPath(), subcommand], {
		env: { ...devScriptEnv(), ...extraEnv },
	});
}

async function isContainerRunning(): Promise<boolean> {
	const result = await execCapture("docker", [
		"inspect",
		"-f",
		"{{.State.Running}}",
		containerName(),
	]);
	return result.isOk && result.output.trim() === "true";
}

const gatewayProbeDeadline = createDeadlinePolicy({
	name: "dev-controls-gateway-probe",
	timeoutMs: GATEWAY_PROBE_TIMEOUT_MS,
});

async function probeGateway(): Promise<{
	readonly isReachable: boolean;
	readonly isBusy: boolean;
	readonly latencyMs: number | null;
}> {
	const startedAt = Date.now();
	try {
		return await gatewayProbeDeadline.run(async (signal) => {
			const response = await fetch(`${gatewayUrl()}/health`, { signal });
			const latencyMs = Date.now() - startedAt;
			if (!response.ok) {
				return { isReachable: false, isBusy: false, latencyMs };
			}
			let isBusy = false;
			try {
				const body = (await response.json()) as { isBusy?: boolean };
				isBusy = body.isBusy === true;
			} catch (error) {
				// A healthy gateway without a JSON body still counts as reachable.
				reportDesktopEdgeFailure("dev-controls", "health-body", error);
			}
			return { isReachable: true, isBusy, latencyMs };
		});
	} catch {
		return { isReachable: false, isBusy: false, latencyMs: null };
	}
}

async function collectBoxStatus(): Promise<SandDevBoxStatus> {
	const [isRunning, gateway] = await Promise.all([isContainerRunning(), probeGateway()]);
	let detail: string;
	if (!isRunning) {
		detail = "Container not running";
	} else if (!gateway.isReachable) {
		detail = "Container up, gateway not reachable yet";
	} else {
		detail = `Gateway healthy${gateway.isBusy ? " (host busy)" : ""}`;
	}
	return {
		containerName: containerName(),
		isContainerRunning: isRunning,
		gatewayUrl: gatewayUrl(),
		isGatewayReachable: gateway.isReachable,
		isHostBusy: gateway.isBusy,
		latencyMs: gateway.latencyMs,
		detail,
	};
}

function parseBoxDoctorOutput(raw: string): SandDevBoxHealth {
	const checks: SandDevBoxHealthCheck[] = [];
	let summary = "";
	for (const line of raw.split("\n")) {
		const checkMatch = /^\[box-doctor\]\s+(PASS|FAIL)\s+([^:]+):\s*(.*)$/.exec(line.trim());
		if (checkMatch != null) {
			checks.push({
				isPass: checkMatch[1] === "PASS",
				name: checkMatch[2].trim(),
				detail: checkMatch[3].trim(),
			});
			continue;
		}
		const summaryMatch = /^\[box-doctor\]\s+SUMMARY:\s*(.*)$/.exec(line.trim());
		if (summaryMatch != null) {
			summary = summaryMatch[1].trim();
		}
	}
	return {
		isOk: checks.length > 0 && checks.every((check) => check.isPass),
		checks,
		summary,
		raw,
	};
}

async function collectBoxHealth(): Promise<SandDevBoxHealth> {
	if (!(await isContainerRunning())) {
		return {
			isOk: false,
			checks: [],
			summary: `Container ${containerName()} is not running`,
			raw: "",
		};
	}
	const result = await execCapture("docker", ["exec", containerName(), "box-doctor"]);
	const health = parseBoxDoctorOutput(result.output);
	if (health.checks.length > 0) return health;
	return {
		isOk: false,
		checks: [],
		summary: result.output.length > 0 ? "box-doctor produced no checks" : "box-doctor failed",
		raw: result.output,
	};
}

function devBoxRootHost(): string {
	// Derived from getSandRootDir (not a hardcoded ~/.cursor/sand-dev) so it
	// follows the --user-data-dir / SAND_USER_DATA_DIR override, matching the
	// dev-box loop's devBoxRoot in scripts/dev-box-docker.mjs.
	return path.join(getSandRootDir(), "dev-box");
}

function formatBytes(bytes: number): string {
	if (bytes < 1024) return `${bytes} B`;
	const units = ["KB", "MB", "GB"];
	let value = bytes / 1024;
	let unit = 0;
	while (value >= 1024 && unit < units.length - 1) {
		value /= 1024;
		unit += 1;
	}
	return `${value.toFixed(1)} ${units[unit]}`;
}

// Reads the durable box store's status straight off the host-side dir the
// dev:box-docker loop mounts into the box (local FS, no S3): the persisted store
// id, the manifest it points at, and the boot copy-in outcome from the box log.
async function collectBoxStoreStatus(): Promise<SandDevBoxStoreStatus> {
	const root = devBoxRootHost();
	let storeId: string | null = null;
	try {
		storeId = (await readFile(path.join(root, "box-store-id"), "utf8")).trim() || null;
	} catch {
		storeId = null;
	}
	let manifestEntries = 0;
	let totalBytes = 0;
	let lastSnapshotMsAgo: number | null = null;
	if (storeId != null) {
		try {
			const parsed = JSON.parse(
				await readFile(path.join(root, "box-store", storeId, "manifest.json"), "utf8"),
			) as {
				updatedAtMs?: number;
				entries?: Record<string, { size?: number }>;
			};
			const entries = parsed.entries ?? {};
			manifestEntries = Object.keys(entries).length;
			for (const entry of Object.values(entries)) {
				if (typeof entry.size === "number" && entry.size > 0) {
					totalBytes += entry.size;
				}
			}
			if (typeof parsed.updatedAtMs === "number" && parsed.updatedAtMs > 0) {
				lastSnapshotMsAgo = Math.max(0, Date.now() - parsed.updatedAtMs);
			}
		} catch (error) {
			// No manifest yet (never snapshotted) or unreadable; leave the zeros.
			reportDesktopEdgeFailure("dev-controls", "snapshot-manifest", error);
		}
	}
	const copyInOutcome = await readCopyInOutcome();
	let detail: string;
	if (storeId == null) {
		detail = "Store not configured (run dev:box)";
	} else if (lastSnapshotMsAgo == null) {
		detail = "No snapshot yet";
	} else {
		detail = `${manifestEntries} files, ${formatBytes(totalBytes)}`;
	}
	return {
		isStoreEnabled: storeId != null,
		lastSnapshotMsAgo,
		manifestEntries,
		totalBytes,
		copyInOutcome,
		detail,
	};
}

// The last boot copy-in outcome, parsed from the in-box copy-in log (a one-shot
// pre-host process, so its result only lives in the log).
async function readCopyInOutcome(): Promise<string> {
	if (!(await isContainerRunning())) return "unknown";
	const result = await execCapture("docker", [
		"exec",
		containerName(),
		"sh",
		"-c",
		"cat /tmp/sand-copy-in.log 2>/dev/null || true",
	]);
	const matches = [...result.output.matchAll(/\[box-copy-in\] result outcome=(\S+)/g)];
	return matches.length > 0 ? matches[matches.length - 1][1] : "none";
}

// The per-box gateway bearer: the desktop's own env wins (set by dev.mjs from the
// descriptor), else the gateway descriptor file the dev:box loop writes.
async function readGatewayToken(): Promise<string | null> {
	const fromEnv = process.env.SAND_HOST_GATEWAY_TOKEN?.trim();
	if (fromEnv != null && fromEnv.length > 0) return fromEnv;
	try {
		const parsed = JSON.parse(
			await readFile(path.join(devBoxRootHost(), "gateway.json"), "utf8"),
		) as { gatewayToken?: string };
		return parsed.gatewayToken ?? null;
	} catch {
		return null;
	}
}

// Force an immediate snapshot-out flush over the in-box host gateway (the same
// command the backend pokes pre-recreate).
async function snapshotBoxStoreNow(): Promise<SandDevCommandResult> {
	const startedAt = Date.now();
	const token = await readGatewayToken();
	if (token == null) {
		return {
			isOk: false,
			exitCode: null,
			output: "No gateway token found (is the box up?).",
			durationMs: Date.now() - startedAt,
		};
	}
	try {
		const response = await fetch(`${gatewayUrl()}/api/snapshotBoxStoreNow`, {
			method: "POST",
			headers: {
				Authorization: `Bearer ${token}`,
				"Content-Type": "application/json",
			},
			body: JSON.stringify({ includeIdleOnly: false }),
		});
		const text = await response.text();
		return {
			isOk: response.ok,
			exitCode: response.ok ? 0 : response.status,
			output: text.length > 0 ? text : `HTTP ${response.status}`,
			durationMs: Date.now() - startedAt,
		};
	} catch (error) {
		return {
			isOk: false,
			exitCode: null,
			output: String(error),
			durationMs: Date.now() - startedAt,
		};
	}
}

// POST a dev control action (reload / restart) to the MAIN app's control server.
// The panel runs in its own process, so it can't reach the main window directly;
// a failure here is expected mid-restart (the main app exits, then re-binds).
async function postControl(pathname: string): Promise<void> {
	try {
		await fetch(`http://127.0.0.1:${resolveDevControlPort()}${pathname}`, {
			method: "POST",
		});
	} catch (error) {
		// The main app is mid-restart (connection reset) — it re-binds on respawn.
		reportDesktopEdgeFailure("dev-controls", "control-post", error);
	}
}

class SandDevThemeControlError extends Error {}

async function fetchTheme(search: string): Promise<SandThemeState> {
	const response = await fetch(`http://127.0.0.1:${resolveDevControlPort()}/theme${search}`, {
		method: search.length === 0 ? "GET" : "POST",
	});
	const body: unknown = await response.json();
	if (!response.ok || !isSandThemeState(body)) {
		throw new SandDevThemeControlError(`theme control failed: HTTP ${response.status}`);
	}
	return body;
}

class SandDevGatewayOfflineControlError extends Error {}

async function fetchGatewayOffline(search: string): Promise<SandDevGatewayOfflineStatus> {
	const response = await fetch(
		`http://127.0.0.1:${resolveDevControlPort()}/gateway-offline${search}`,
		{ method: search.length === 0 ? "GET" : "POST" },
	);
	const body = (await response.json()) as {
		induced?: unknown;
		error?: unknown;
	};
	if (!response.ok || typeof body.induced !== "boolean") {
		throw new SandDevGatewayOfflineControlError(
			typeof body.error === "string"
				? body.error
				: `gateway-offline control failed: HTTP ${response.status}`,
		);
	}
	return { induced: body.induced };
}

async function tailBoxLogs(): Promise<SandDevCommandResult> {
	if (!(await isContainerRunning())) {
		return {
			isOk: false,
			exitCode: null,
			output: `Container ${containerName()} is not running.`,
			durationMs: 0,
		};
	}
	return await execCapture("docker", [
		"exec",
		containerName(),
		"sh",
		"-c",
		// The host's stdout rides its own /tmp/sand-host.log (split out by the
		// supervisor); show both so the in-box host + supervisor are together.
		`touch /tmp/sand-supervisor.log /tmp/sand-host.log; tail -n ${LOG_TAIL_LINES} /tmp/sand-supervisor.log /tmp/sand-host.log`,
	]);
}

async function readBoxStoreLogs(): Promise<SandDevCommandResult> {
	if (!(await isContainerRunning())) {
		return {
			isOk: false,
			exitCode: null,
			output: `Container ${containerName()} is not running.`,
			durationMs: 0,
		};
	}
	return await execCapture("docker", [
		"exec",
		containerName(),
		"sh",
		"-c",
		`touch /tmp/sand-host.log /tmp/sand-copy-in.log; grep -hF -e '[box-store-sync]' -e '[box-copy-in]' /tmp/sand-host.log /tmp/sand-copy-in.log | tail -n ${LOG_TAIL_LINES}`,
	]);
}

async function nukeBox(): Promise<SandDevCommandResult> {
	return await execCapture("bash", [path.join(sandProjectDir(), "box", "nuke-sand-box.sh")]);
}

async function openBoxDesktop(): Promise<void> {
	const url = new URL(gatewayUrl());
	url.port = String(NOVNC_PORT);
	url.pathname = "/vnc.html";
	await shell.openExternal(url.toString());
}

function isDevControlsPanelSender(sender: Electron.WebContents): boolean {
	return (
		devControlsWindow != null &&
		!devControlsWindow.isDestroyed() &&
		sender === devControlsWindow.webContents
	);
}

function devControlsEdgeTransport(): EdgeServerTransport<DevControlsSenderFacts> {
	return {
		handle: (channel, run) => {
			ipcMain.handle(channel, (event, payload: unknown) =>
				run({ isDevControlsPanel: isDevControlsPanelSender(event.sender) }, payload),
			);
		},
		removeHandler: (channel) => {
			ipcMain.removeHandler(channel);
		},
		broadcast: () => {},
	};
}

export function serveDevControlsEdge(): void {
	serveEdge(devControlsRpcContract, DEV_CONTROLS_METHOD_TABLE, {
		transport: devControlsEdgeTransport(),
		trust: createDevControlsTrust(),
		handlers: createDevControlsHandlers({
			postControl,
			fetchTheme,
			fetchGatewayOffline,
			collectBoxStatus,
			collectBoxHealth,
			runDevBoxScript,
			// The REAL in-box host-upgrade poke (distinct from "Upgrade host", which is
			// the local dev-loop bundle sync): drives the same `/api/updateHostNow` gateway
			// command the backend admin "Update host" uses, so the in-box host genuinely
			// resolves + fetches the published bundle from S3 and stages it for the
			// supervisor swap. Like the snapshot-flush poke, it targets the LOCAL dev box via
			// the same loopback gateway descriptor (`gatewayUrl()` + `readGatewayToken()`);
			// the brokered "Attach prod box" path is not reached by the panel's gateway pokes
			// (the panel is a separate process without the main app's brokered connection /
			// pod-network token), and the host's raw-error gate refuses a prod box regardless.
			pokeHostUpgrade: async () =>
				await pokeHostUpgrade({
					gatewayBaseUrl: gatewayUrl(),
					token: await readGatewayToken(),
				}),
			tailBoxLogs,
			nukeBox,
			openBoxDesktop,
			collectBoxStoreStatus,
			snapshotBoxStoreNow,
			boxStoreLogs: readBoxStoreLogs,
			getAttachProdBoxStatus: () => getAttachProdBoxStatus(),
			writeAttachProdBoxPrefs: (enabled) => {
				writeAttachProdBoxPrefs(enabled);
			},
			onePasswordCli: onePasswordCliDevController,
		}),
	});
}

export function openDevControlsWindow(): void {
	const devServerUrl = process.env.VITE_DEV_SERVER_URL;
	// The panel's renderer is served by the vite dev server; without it (a
	// packaged build, or `start` without dev) there is nothing to load.
	if (devServerUrl == null || devServerUrl.length === 0) return;
	if (devControlsWindow != null && !devControlsWindow.isDestroyed()) {
		devControlsWindow.focus();
		return;
	}

	const width = 780;
	const height = 600;
	const margin = 16;
	const { workArea } = screen.getPrimaryDisplay();
	const window = new BrowserWindow({
		width,
		height,
		minWidth: 660,
		minHeight: 460,
		x: workArea.x + workArea.width - width - margin,
		y: workArea.y + margin,
		title: "Grok Bot Dev Controls",
		resizable: true,
		minimizable: true,
		maximizable: true,
		fullscreenable: false,
		backgroundColor: "#0f1117",
		autoHideMenuBar: true,
		webPreferences: {
			contextIsolation: true,
			nodeIntegration: false,
			// The panel entry (electron-dev-controls/main.cts) bundles this module
			// and runs from dist/electron-dev-controls, so the panel preload
			// resolves from the sibling dist/electron-preload dir — the same shape
			// the main window uses for its preloads.
			preload: path.join(__dirname, "..", "electron-preload", "preload-dev-controls.cjs"),
			sandbox: false,
		},
	});
	window.setMenuBarVisibility(false);
	devControlsWindow = window;
	window.on("closed", () => {
		devControlsWindow = undefined;
	});

	const target = new URL(
		"src/electron-dev-controls/page/dev-controls.html",
		devServerUrl.endsWith("/") ? devServerUrl : `${devServerUrl}/`,
	).href;
	void window.loadURL(target);
}
