import { type Clock, realClock } from "@sand/dune/scheduling";

// Resolves after `ms` milliseconds. When an `AbortSignal` is supplied the wait
// is cut short the moment the signal aborts (resolving, never rejecting), so a
// pending delay never outlives the work it was guarding. Timers always unref
// (the Dune clock's stance): a pending delay never keeps the process alive.
export function delay(ms: number, signal?: AbortSignal): Promise<void> {
	return delayWith(realClock, ms, signal);
}

export function delayWith(clock: Clock, ms: number, signal?: AbortSignal): Promise<void> {
	return new Promise((resolve) => {
		if (signal?.aborted === true) {
			resolve();
			return;
		}
		const onAbort = (): void => {
			scheduled.dispose();
			resolve();
		};
		const scheduled = clock.schedule(Number.isFinite(ms) && ms > 0 ? ms : 0, () => {
			signal?.removeEventListener("abort", onAbort);
			resolve();
		});
		signal?.addEventListener("abort", onAbort, { once: true });
	});
}
