export interface RpcMethod<Args, Reply> {
	readonly args: Args;
	readonly reply: Reply;
}

export interface RpcContractShape {
	readonly methods: Record<string, RpcMethod<unknown, unknown>>;
	readonly events: Record<string, unknown>;
	readonly capabilities: string;
	readonly failureCodes: string;
}

export type RpcMethodFn<C extends RpcContractShape, M extends keyof C["methods"]> = (
	args: C["methods"][M]["args"],
) => Promise<C["methods"][M]["reply"]>;

export type RpcClientOf<C extends RpcContractShape> = {
	readonly [M in keyof C["methods"]]: RpcMethodFn<C, M>;
};

export type RpcEventHandlers<C extends RpcContractShape> = {
	readonly [E in keyof C["events"]]?: (payload: C["events"][E]) => void;
};

export type RpcEventsDeclared<C extends RpcContractShape> =
	C["events"] extends Record<string, never> ? false : true;

export interface RpcContractTag<C extends RpcContractShape> {
	readonly edge: string;
	readonly hasEvents: boolean;
	readonly __shape?: C;
}

export function declareRpcContract<C extends RpcContractShape>(
	edge: string,
	...events: RpcEventsDeclared<C> extends true ? ["events"] : []
): RpcContractTag<C> {
	return { edge, hasEvents: events.length > 0 };
}

export type EdgeMethodTable<C extends RpcContractShape> = {
	readonly [M in keyof C["methods"]]: {
		readonly args: C["methods"][M]["args"] extends Record<string, never> ? "none" : "object";
	};
};
