import { createDeadlinePolicy } from "@sand/dune/scheduling";

import { type SandHostUpdateResult } from "../../host/gateway-protocol.js";
import { GATEWAY_API_PREFIX } from "../../shared/gateway-wire.js";
import type { SandDevCommandResult } from "../../shared/rpc/dev-controls.js";

// DEV-ONLY driver for the Dev Controls "Poke host upgrade" button. It drives the
// REAL in-box host-upgrade poke — the same gateway command the backend admin
// "Update host" uses — by POSTing `/api/updateHostNow` to the box gateway (NOT a
// mock, and NOT the local dev-loop bundle sync the neighboring "Upgrade host"
// button runs). The in-box host then resolves the latest published bundle, fetches
// its bytes from the public S3 bucket, and stages them for the supervisor to
// hot-swap in place — producing a real `sand.host.upgrade` telemetry event.
//
// It passes `includeErrorDetail: true`, the dev-only opt-in that makes the host
// return the raw fetch/stage error WITH its full cause chain + `@phase` in
// `reason` (production telemetry ships only the bounded `@error_class`), so a
// transient phase:fetch fetch() TypeError cause — the thing the 0%-poke
// investigation is hunting — is surfaced verbatim in the dev output.
//
// Kept electron-free (deps injected) so the genuine-path wiring and the raw-error
// surfacing are unit-testable with a fake fetch.

// Bound the whole updateHostNow round-trip (the host fetches the bundle from S3 +
// stages it within the RPC, so allow a generous budget) so a wedged/asleep box
// aborts instead of hanging the dev poke forever — mirroring the backend admin
// poke's AbortSignal.timeout.
const POKE_TIMEOUT_MS = 30_000;

export interface HostUpgradePokeDeps {
	// The box gateway base URL (scheme + host + port), e.g. http://127.0.0.1:1340.
	readonly gatewayBaseUrl: string;
	// The per-box gateway bearer, or null when it could not be resolved (box down).
	readonly token: string | null;
	// Injectable for tests; defaults to the global fetch.
	readonly fetchFn?: typeof fetch;
	// Injectable for tests; defaults to Date.now.
	readonly now?: () => number;
	// Request timeout; defaults to POKE_TIMEOUT_MS.
	readonly timeoutMs?: number;
}

// Format the host's updateHostNow result for the Dev Controls OUTPUT pane. Kept
// pure + exported so the outcome mapping (esp. surfacing the raw failure `reason`
// verbatim) is directly testable.
export function formatHostUpgradePokeOutcome(result: SandHostUpdateResult): {
	readonly isOk: boolean;
	readonly output: string;
} {
	const version = typeof result.version === "string" ? result.version : "";
	const reason = typeof result.reason === "string" ? result.reason : "";
	if (result.started === true) {
		return {
			isOk: true,
			output: [
				"outcome: staged (real updateHostNow — fetch + stage OK)",
				version.length > 0 ? `to_version: ${version}` : undefined,
				"The supervisor hot-swaps the bundle at its next idle tick (forced) and " +
					"emits sand.host.upgrade @phase:swap. Watch Box logs for the swap outcome.",
			]
				.filter((line): line is string => line != null)
				.join("\n"),
		};
	}
	// A no-op: the box is already on the latest published bundle. The poke still
	// reached the host + resolved the source, so it is a green (successful) outcome.
	if (reason === "already-latest") {
		return {
			isOk: true,
			output: `outcome: no-op — host already on latest${
				version.length > 0 ? ` (${version})` : ""
			}. Nothing to fetch/stage.`,
		};
	}
	// Any other non-started outcome is a genuine failure/skip. Surface `reason`
	// VERBATIM: for a phase:fetch failure (includeErrorDetail was set) it carries the
	// raw fetch() error + its full cause chain — the dev-only detail prod telemetry
	// strips to `@error_class`.
	return {
		isOk: false,
		output: [
			"outcome: not started",
			`reason: ${reason.length > 0 ? reason : "(no reason returned)"}`,
		].join("\n"),
	};
}

// Drive the genuine in-box host-upgrade poke and shape it for the dev OUTPUT pane.
// Best-effort: never throws (a token-less box, an HTTP error, or a request failure
// all resolve to an isOk:false result the panel renders).
export async function pokeHostUpgrade(deps: HostUpgradePokeDeps): Promise<SandDevCommandResult> {
	const fetchFn = deps.fetchFn ?? fetch;
	const now = deps.now ?? Date.now;
	const startedAt = now();
	const elapsedMs = (): number => now() - startedAt;

	if (deps.token == null || deps.token.length === 0) {
		return {
			isOk: false,
			exitCode: null,
			output: "No gateway token found (is the box up?).",
			durationMs: elapsedMs(),
		};
	}

	const pokeDeadline = createDeadlinePolicy({
		name: "dev-host-upgrade-poke",
		timeoutMs: deps.timeoutMs ?? POKE_TIMEOUT_MS,
	});
	try {
		return await pokeDeadline.run(async (signal) => {
			const response = await fetchFn(`${deps.gatewayBaseUrl}${GATEWAY_API_PREFIX}/updateHostNow`, {
				method: "POST",
				headers: {
					Authorization: `Bearer ${deps.token}`,
					"Content-Type": "application/json",
				},
				// `force` escalates past the supervisor's idle-defer window (graceful
				// interrupt -> apply -> resume), matching the admin poke's default;
				// `includeErrorDetail` is the DEV-ONLY raw-error opt-in.
				body: JSON.stringify({ force: true, includeErrorDetail: true }),
				signal,
			});
			if (!response.ok) {
				const detail = await response.text().catch(() => "");
				return {
					isOk: false,
					exitCode: response.status,
					output: `updateHostNow HTTP ${response.status}${detail.length > 0 ? `\n${detail}` : ""}`,
					durationMs: elapsedMs(),
				};
			}
			const body = (await response.json()) as SandHostUpdateResult;
			const outcome = formatHostUpgradePokeOutcome(body);
			return {
				isOk: outcome.isOk,
				// A semantic failure (HTTP 200 but started:false, e.g. a @phase:fetch
				// failure) must not report `exit 0` in the OUTPUT footer — map it to a
				// non-zero code like the neighboring snapshot poke maps HTTP failures.
				exitCode: outcome.isOk ? 0 : 1,
				output: outcome.output,
				durationMs: elapsedMs(),
			};
		});
	} catch (error) {
		return {
			isOk: false,
			exitCode: null,
			output: `updateHostNow request failed: ${String(error)}`,
			durationMs: elapsedMs(),
		};
	}
}
