import { execFile } from "node:child_process";

import {
	OnePasswordProvisioningError,
	type OnePasswordOpExecutor,
	type OnePasswordOpResult,
} from "./onepassword-provisioning-contract.js";

type ProcessFailureKind =
	| "conflict"
	| "denied"
	| "integration-off"
	| "permission"
	| "timeout"
	| "unknown";

class OnePasswordProcessError extends Error {
	constructor(
		readonly processCode: unknown,
		readonly killed: boolean,
		readonly failureKind: ProcessFailureKind,
	) {
		super("The 1Password CLI command failed.");
		this.name = "OnePasswordProcessError";
	}
}

function failureKind(raw: string): ProcessFailureKind {
	const text = raw.toLowerCase();
	if (
		text.includes("authorization prompt dismissed") ||
		text.includes("request was denied") ||
		text.includes("authorization denied") ||
		text.includes("rejected")
	) {
		return "denied";
	}
	if (
		text.includes("connecting to desktop app") ||
		text.includes("desktop app not running") ||
		text.includes("cli is not enabled") ||
		text.includes("couldn't connect to the 1password app") ||
		text.includes("no accounts configured")
	) {
		return "integration-off";
	}
	if (
		text.includes("permission") ||
		text.includes("not allowed") ||
		text.includes("(403)") ||
		text.includes("forbidden")
	) {
		return "permission";
	}
	if (text.includes("already exists") || text.includes("(409)") || text.includes("conflict")) {
		return "conflict";
	}
	if (text.includes("etimedout") || text.includes("timed out")) {
		return "timeout";
	}
	return "unknown";
}

export function createOnePasswordOpExecutor(): OnePasswordOpExecutor {
	return async (file, args, options) =>
		await new Promise<OnePasswordOpResult>((resolve, reject) => {
			execFile(
				file,
				[...args],
				{
					signal: options.signal,
					timeout: options.timeoutMs,
					maxBuffer: options.maxBufferBytes,
					windowsHide: true,
					env: { ...options.env },
				},
				(error, stdout, stderr) => {
					if (error != null) {
						reject(
							new OnePasswordProcessError(
								Reflect.get(error, "code"),
								Reflect.get(error, "killed") === true,
								failureKind(`${error.message}\n${stderr.toString()}`),
							),
						);
						return;
					}
					resolve({ stdout: stdout.toString(), stderr: stderr.toString() });
				},
			);
		});
}

export function classifyOnePasswordProcessFailure(error: unknown): OnePasswordProvisioningError {
	if (error instanceof OnePasswordProvisioningError) return error;
	if (
		error instanceof DOMException &&
		(error.name === "AbortError" || error.name === "TimeoutError")
	) {
		return new OnePasswordProvisioningError(
			error.name === "AbortError" ? "cancelled" : "timeout",
			error.name === "AbortError"
				? "The 1Password operation was canceled."
				: "The 1Password operation timed out.",
		);
	}
	const processError = error instanceof OnePasswordProcessError ? error : undefined;
	const processCode =
		processError?.processCode ??
		(typeof error === "object" && error != null ? Reflect.get(error, "code") : undefined);
	const killed =
		processError?.killed ??
		(typeof error === "object" && error != null && Reflect.get(error, "killed") === true);
	if (processCode === "ENOENT") {
		return new OnePasswordProvisioningError(
			"missing-cli",
			"The secure 1Password CLI runtime is unavailable.",
		);
	}
	if (processCode === "ABORT_ERR") {
		return new OnePasswordProvisioningError("cancelled", "The 1Password operation was canceled.");
	}
	const raw = error instanceof Error ? error.message : "";
	const kind = processError?.failureKind ?? failureKind(raw);
	if (killed || kind === "timeout") {
		return new OnePasswordProvisioningError(
			"timeout",
			"The 1Password desktop app did not respond in time.",
		);
	}
	if (kind === "denied") {
		return new OnePasswordProvisioningError(
			"denied",
			"The request was not approved in the 1Password desktop app.",
		);
	}
	if (kind === "integration-off") {
		return new OnePasswordProvisioningError(
			"integration-off",
			"1Password desktop CLI integration is unavailable.",
		);
	}
	if (kind === "permission") {
		return new OnePasswordProvisioningError(
			"permission",
			"The selected 1Password account does not allow this operation.",
		);
	}
	if (kind === "conflict") {
		return new OnePasswordProvisioningError(
			"conflict",
			"The requested 1Password object already exists.",
		);
	}
	return new OnePasswordProvisioningError("op-error", "The secure 1Password CLI operation failed.");
}

export function classifyOnePasswordRuntimeFailure(error: unknown): OnePasswordProvisioningError {
	if (error instanceof OnePasswordProvisioningError) return error;
	if (
		error instanceof DOMException &&
		(error.name === "AbortError" || error.name === "TimeoutError")
	) {
		return new OnePasswordProvisioningError(
			error.name === "AbortError" ? "cancelled" : "timeout",
			error.name === "AbortError"
				? "The 1Password operation was canceled."
				: "The secure 1Password runtime verification timed out.",
		);
	}
	const processCode =
		typeof error === "object" && error != null ? Reflect.get(error, "code") : undefined;
	if (processCode === "ABORT_ERR") {
		return new OnePasswordProvisioningError("cancelled", "The 1Password operation was canceled.");
	}
	if (processCode === "ENOENT") {
		return new OnePasswordProvisioningError(
			"missing-cli",
			"The secure 1Password CLI runtime is unavailable.",
		);
	}
	return new OnePasswordProvisioningError(
		"op-error",
		"The secure 1Password runtime failed verification.",
	);
}
