import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

// Preference file for "attach this dev desktop to the prod brokered box tenant".
// Default off. Read by scripts/dev.mjs (spawn env), main.cts (SAND_PACKAGED pin),
// Dev Controls UI, and the main-window preload so CDP / control-sand can see it.
//
// Path lives under ~/.cursor/sand-dev so a packaged build never touches it.
export const ATTACH_PROD_BOX_PREFS_PATH = join(
	homedir(),
	".cursor",
	"sand-dev",
	"attach-prod-box.json",
);

export interface AttachProdBoxPrefs {
	readonly enabled: boolean;
	readonly updatedAtMs: number;
}

// The status shape crosses the dev-controls edge (the panel renders it), so it
// lives in the edge declaration; the re-export keeps this module's other
// consumers (main.cts, the sand-dev and desktop capabilities) on their path.
export type { AttachProdBoxStatus } from "../../shared/rpc/dev-controls.js";
import type { AttachProdBoxStatus } from "../../shared/rpc/dev-controls.js";

const DEFAULT_PREFS: AttachProdBoxPrefs = {
	enabled: false,
	updatedAtMs: 0,
};

export function readAttachProdBoxPrefs(): AttachProdBoxPrefs {
	try {
		const raw = readFileSync(ATTACH_PROD_BOX_PREFS_PATH, "utf8");
		const parsed: unknown = JSON.parse(raw);
		if (
			parsed == null ||
			typeof parsed !== "object" ||
			!("enabled" in parsed) ||
			typeof (parsed as { enabled: unknown }).enabled !== "boolean"
		) {
			return DEFAULT_PREFS;
		}
		const updatedAtMs =
			"updatedAtMs" in parsed &&
			typeof (parsed as { updatedAtMs: unknown }).updatedAtMs === "number"
				? (parsed as { updatedAtMs: number }).updatedAtMs
				: 0;
		return {
			enabled: (parsed as { enabled: boolean }).enabled,
			updatedAtMs,
		};
	} catch {
		return DEFAULT_PREFS;
	}
}

export function writeAttachProdBoxPrefs(enabled: boolean): AttachProdBoxPrefs {
	const prefs: AttachProdBoxPrefs = {
		enabled,
		updatedAtMs: Date.now(),
	};
	mkdirSync(dirname(ATTACH_PROD_BOX_PREFS_PATH), { recursive: true });
	writeFileSync(ATTACH_PROD_BOX_PREFS_PATH, `${JSON.stringify(prefs, null, 2)}\n`, "utf8");
	return prefs;
}

// Env wins when explicitly set (CLI / CI). Otherwise the preference file.
// Callers that spawn Electron should set SAND_ATTACH_PROD_BOX from this.
export function resolveAttachProdBoxPreferred(env: NodeJS.ProcessEnv = process.env): boolean {
	const raw = env.SAND_ATTACH_PROD_BOX?.trim();
	if (raw === "1") return true;
	if (raw === "0") return false;
	return readAttachProdBoxPrefs().enabled;
}

// True for this process: either the spawn env was set, or we resolved packaged
// identity via attach (SAND_PACKAGED=1 while not app.isPackaged is set in main).
export function isAttachProdBoxActive(env: NodeJS.ProcessEnv = process.env): boolean {
	return env.SAND_ATTACH_PROD_BOX === "1";
}

export function getAttachProdBoxStatus(env: NodeJS.ProcessEnv = process.env): AttachProdBoxStatus {
	const prefs = readAttachProdBoxPrefs();
	return {
		preferred: resolveAttachProdBoxPreferred(env),
		active: isAttachProdBoxActive(env),
		prefsPath: ATTACH_PROD_BOX_PREFS_PATH,
		updatedAtMs: prefs.updatedAtMs,
	};
}
