import { edgeFamily, type EdgeHandlers, type EdgeTrustPolicies } from "@sand/dune/rpc";

import type { SandThemeState } from "../../shared/desktop.js";
import type {
	AttachProdBoxStatus,
	DevControlsRpcContract,
	SandDevBoxHealth,
	SandDevBoxStatus,
	SandDevBoxStoreStatus,
	SandDevCommandResult,
	SandDevGatewayOfflineStatus,
	SandDevOnePasswordCheckResult,
	SandDevOnePasswordCliStatus,
} from "../../shared/rpc/dev-controls.js";

export interface DevControlsSenderFacts {
	readonly isDevControlsPanel: boolean;
}

export function createDevControlsTrust() {
	return {
		// The panel app opens exactly one window; authorize by webContents identity.
		devControlsPanel: {
			kind: "require",
			test: (sender: DevControlsSenderFacts) => sender.isDevControlsPanel,
			denial: "The dev-controls edge is only accessible from the Dev Controls panel window.",
		},
	} as const satisfies EdgeTrustPolicies<DevControlsSenderFacts>;
}

export type DevControlsTrust = ReturnType<typeof createDevControlsTrust>;

const family = edgeFamily<DevControlsRpcContract, DevControlsSenderFacts, DevControlsTrust>();

export type SandDevBoxScriptCommand =
	| "sync"
	| "rebuild"
	| "up"
	| "down"
	| "recreate-fresh"
	| "clear-store";

export interface DevControlsEdgeDeps {
	postControl(pathname: string): Promise<void>;
	fetchTheme(search: string): Promise<SandThemeState>;
	fetchGatewayOffline(search: string): Promise<SandDevGatewayOfflineStatus>;
	collectBoxStatus(): Promise<SandDevBoxStatus>;
	collectBoxHealth(): Promise<SandDevBoxHealth>;
	runDevBoxScript(subcommand: SandDevBoxScriptCommand): Promise<SandDevCommandResult>;
	pokeHostUpgrade(): Promise<SandDevCommandResult>;
	tailBoxLogs(): Promise<SandDevCommandResult>;
	nukeBox(): Promise<SandDevCommandResult>;
	openBoxDesktop(): Promise<void>;
	collectBoxStoreStatus(): Promise<SandDevBoxStoreStatus>;
	snapshotBoxStoreNow(): Promise<SandDevCommandResult>;
	boxStoreLogs(): Promise<SandDevCommandResult>;
	getAttachProdBoxStatus(): AttachProdBoxStatus;
	writeAttachProdBoxPrefs(enabled: boolean): void;
	onePasswordCli: {
		inspect(): Promise<SandDevOnePasswordCliStatus>;
		prepare(): Promise<SandDevOnePasswordCliStatus>;
		cancel(): void;
		listAccounts(): Promise<SandDevOnePasswordCheckResult>;
		listVaults(): Promise<SandDevOnePasswordCheckResult>;
		findDefaultVault(): Promise<SandDevOnePasswordCheckResult>;
		runSyntheticProvisioning(): Promise<SandDevOnePasswordCheckResult>;
	};
}

export function createDevControlsHandlers(
	deps: DevControlsEdgeDeps,
): EdgeHandlers<DevControlsRpcContract, DevControlsSenderFacts, DevControlsTrust> {
	return {
		...family("devControlsPanel", {
			restartElectron: () => deps.postControl("/restart"),
			reloadWindow: () => deps.postControl("/reload"),
			restartOnboarding: () => deps.postControl("/restart-onboarding"),
			skipOnboarding: () => deps.postControl("/skip-onboarding"),
			themeStatus: () => deps.fetchTheme(""),
			setThemePreference: ({ preference }) =>
				deps.fetchTheme(`?preference=${encodeURIComponent(preference)}`),
			setWidgetGallery: ({ isOn }) =>
				deps.postControl(`/widget-gallery?on=${isOn === true ? "1" : "0"}`),
			gatewayOfflineStatus: () => deps.fetchGatewayOffline(""),
			setGatewayOffline: ({ induced }) =>
				deps.fetchGatewayOffline(`?induced=${induced === true ? "1" : "0"}`),
			onePasswordCliStatus: () => deps.onePasswordCli.inspect(),
			prepareOnePasswordCli: () => deps.onePasswordCli.prepare(),
			cancelOnePasswordCliPrepare: () => {
				deps.onePasswordCli.cancel();
			},
			onePasswordAccounts: () => deps.onePasswordCli.listAccounts(),
			onePasswordVaults: () => deps.onePasswordCli.listVaults(),
			onePasswordFindVault: () => deps.onePasswordCli.findDefaultVault(),
			onePasswordSyntheticProvisioning: () => deps.onePasswordCli.runSyntheticProvisioning(),
			attachProdBoxStatus: () => deps.getAttachProdBoxStatus(),
			setAttachProdBoxEnabled: async ({ enabled, isRestartMainApp }) => {
				deps.writeAttachProdBoxPrefs(enabled === true);
				const status = deps.getAttachProdBoxStatus();
				if (isRestartMainApp !== false) {
					// Preference only applies on next main Electron spawn (dev.mjs + main boot).
					await deps.postControl("/restart");
				}
				return status;
			},
			boxStatus: () => deps.collectBoxStatus(),
			boxHealth: () => deps.collectBoxHealth(),
			upgradeHost: () => deps.runDevBoxScript("sync"),
			pokeHostUpgrade: () => deps.pokeHostUpgrade(),
			rebuildBox: async () => {
				// Tell the main app a box rebuild is starting so it raises the same cover the
				// production recreate path does — this local-docker rebuild recreates the
				// container directly and never publishes a backend migration phase, so the
				// desktop has no other cue. Best-effort: the rebuild runs regardless.
				await deps.postControl("/box-rebuild-start");
				return await deps.runDevBoxScript("rebuild");
			},
			tailLogs: () => deps.tailBoxLogs(),
			startBox: () => deps.runDevBoxScript("up"),
			teardownBox: () => deps.runDevBoxScript("down"),
			nukeBox: () => deps.nukeBox(),
			openDesktop: () => deps.openBoxDesktop(),
			boxStoreStatus: () => deps.collectBoxStoreStatus(),
			boxStoreSnapshotNow: () => deps.snapshotBoxStoreNow(),
			boxStoreLogs: () => deps.boxStoreLogs(),
			boxStoreRecreateFresh: () => deps.runDevBoxScript("recreate-fresh"),
			boxStoreClear: () => deps.runDevBoxScript("clear-store"),
		}),
	};
}
