// `preference` is what the user picks and we persist; `resolved` is the
// concrete light/dark theme actually applied to the renderer after folding
// `system` through the OS color scheme.

export const SAND_THEME_PREFERENCES = ["system", "light", "dark"] as const;

export type SandThemePreference = (typeof SAND_THEME_PREFERENCES)[number];

export type SandResolvedTheme = "light" | "dark";

export const DEFAULT_SAND_THEME_PREFERENCE: SandThemePreference = "system";

export interface SandThemeState {
	readonly preference: SandThemePreference;
	readonly resolved: SandResolvedTheme;
}

export function isSandThemePreference(value: unknown): value is SandThemePreference {
	return typeof value === "string" && (SAND_THEME_PREFERENCES as readonly string[]).includes(value);
}

export function isSandThemeState(value: unknown): value is SandThemeState {
	if (typeof value !== "object" || value == null || Array.isArray(value)) return false;
	if (!("preference" in value) || !isSandThemePreference(value.preference)) return false;
	return "resolved" in value && (value.resolved === "light" || value.resolved === "dark");
}

export interface SandWindowState {
	readonly isFullscreen: boolean;
	readonly isMaximized: boolean;
}

export type SandDesktopPlatform = "darwin" | "win32" | "linux" | "other";

export interface SandDesktopEnvironment {
	readonly platform: SandDesktopPlatform;
	readonly isDev: boolean;
}

export interface SandWidgetGalleryEvent {
	readonly isOn: boolean;
}

/** Dev-only local-box rebuild event; packaged builds never emit it. */
export interface SandDevBoxRebuildEvent {
	readonly type: "start";
}

// Dev-only: the live image-download percent of a dev-box recreate run by the
// desktop's local Docker control plane (channel "sand:dev-box-pull-progress").
// The desktop process performs the real `docker pull` there, so it is also the
// only process that can observe the pull's byte progress — the in-box host,
// which reports pull progress everywhere else, is down during its own box's
// recreate. Never emitted in packaged builds.
export interface SandDevBoxPullProgressEvent {
	readonly percent: number;
}

export type SandDeepLinkSource = "protocol" | "https";

// The validated OS deep-link routes, produced only by the parser in
// sand/src/shared/deep-link.ts and revalidated at the renderer IPC boundary
// with `isSandDeepLink`. Future routes extend this as a discriminated union
// on `route`.
export type SandDeepLink =
	| {
			readonly version: 1;
			readonly route: "info";
			readonly topic: "deep-links";
			readonly source: SandDeepLinkSource;
	  }
	| {
			readonly version: 1;
			readonly route: "plugin-add";
			readonly pluginId: string;
			readonly source: SandDeepLinkSource;
	  }
	| {
			readonly version: 1;
			readonly route: "open";
			readonly source: SandDeepLinkSource;
	  };

export function isSandDeepLinkPluginId(value: unknown): value is string {
	return typeof value === "string" && /^[0-9]{1,19}$/.test(value);
}

export const SAND_PLUGIN_DEEP_LINK_PATH = "/v1/plugin/add";

export function buildSandPluginDeepLink(pluginId: string): string {
	return `sand://app${SAND_PLUGIN_DEEP_LINK_PATH}?id=${encodeURIComponent(pluginId)}`;
}

// Renderer-side revalidation of the IPC payload: the preload channel is typed,
// but the renderer treats anything crossing the bridge as untrusted and drops
// malformed payloads instead of throwing mid-dispatch.
export function isSandDeepLink(value: unknown): value is SandDeepLink {
	if (typeof value !== "object" || value == null) return false;
	if (!("version" in value) || value.version !== 1) return false;
	if (!("source" in value)) return false;
	if (!("route" in value)) return false;
	switch (value.route) {
		case "info":
			return (
				"topic" in value &&
				value.topic === "deep-links" &&
				(value.source === "protocol" || value.source === "https")
			);
		case "plugin-add":
			return (
				"pluginId" in value &&
				isSandDeepLinkPluginId(value.pluginId) &&
				(value.source === "protocol" || value.source === "https")
			);
		case "open":
			return value.source === "protocol" || value.source === "https";
		default:
			return false;
	}
}

// The desktop's timezone state as one renderer-facing shape: what auto-detect
// resolved on this machine (null when the runtime can't), and the user's
// explicit choice (null = follow auto-detection). The effective zone is
// `overrideTimeZone ?? detectedTimeZone`.
export interface SandTimeZoneSetting {
	readonly detectedTimeZone: string | null;
	readonly overrideTimeZone: string | null;
}

export function isSandTimeZoneSetting(value: unknown): value is SandTimeZoneSetting {
	if (typeof value !== "object" || value == null || Array.isArray(value)) return false;
	if (!("detectedTimeZone" in value) || !("overrideTimeZone" in value)) return false;
	return (
		(value.detectedTimeZone === null || typeof value.detectedTimeZone === "string") &&
		(value.overrideTimeZone === null || typeof value.overrideTimeZone === "string")
	);
}
