// Sand's desktop (Electron main) and host (the headless brain) are long-lived
// processes that together back the entire app. Node's default reaction to an
// uncaught exception or an unhandled promise rejection is to terminate the
// process — which, for either of these, takes the whole app down. That is the
// shape of the import crash: any error thrown *outside* the gateway's awaited
// request handler (e.g. a fire-and-forget `void this.emitAgents()` or
// `void this.sourceMap.getOrCreate(...)` triggered while applying an import)
// becomes an unhandled rejection with nothing to catch it. This module installs
// the last-resort handlers that log such errors and deliberately keep the
// process running, so no single stray failure can crash the app.

export type SandProcessCrashKind = "uncaughtException" | "unhandledRejection";

export type SandProcessFatalKind = SandProcessCrashKind | "fatal";

export type SandProcessCrashReporter = (error: Error, kind: SandProcessCrashKind) => void;

export interface SandProcessCrashGuardOptions {
	readonly scope: string;
	readonly onError?: SandProcessCrashReporter;
}

export interface SandProcessCrashGuards {
	setReporter(onError: SandProcessCrashReporter | undefined): void;
}

function toError(value: unknown): Error {
	return value instanceof Error ? value : new Error(String(value));
}

export function handleProcessCrash(
	options: SandProcessCrashGuardOptions,
	kind: SandProcessCrashKind,
	value: unknown,
): void {
	const error = toError(value);
	console.error(`[${options.scope}] ${kind} (kept alive):`, error);
	try {
		options.onError?.(error, kind);
	} catch {}
}

// Installs the process-wide safety net. Having a listener for these events is
// what suppresses Node's default exit, and the handler never calls
// `process.exit`, so the process stays up after a stray error. Returns a handle
// for late-binding the reporter (see SandProcessCrashGuards).
export function installProcessCrashGuards(
	options: SandProcessCrashGuardOptions,
): SandProcessCrashGuards {
	let reporter = options.onError;
	const report = (kind: SandProcessCrashKind, value: unknown): void =>
		handleProcessCrash({ scope: options.scope, onError: reporter }, kind, value);
	process.on("uncaughtException", (value) => report("uncaughtException", value));
	process.on("unhandledRejection", (value) => report("unhandledRejection", value));
	return {
		setReporter: (onError) => {
			reporter = onError;
		},
	};
}
