/** Returns whether the packaged-build stamp is set. Missing stamps are dev-safe. */
export function isSandPackaged(): boolean {
	return process.env.SAND_PACKAGED === "1";
}

/** Returns whether the side-by-side Sand Lab stamp is set. */
export function isSandLabBuild(): boolean {
	return process.env.SAND_LAB === "1";
}

/** State and box-tenant scope for packaged, dev, and lab builds. */
export type SandVariant = "sand" | "sand-dev" | "sand-lab";

export function getSandVariant(): SandVariant {
	return !isSandPackaged() ? "sand-dev" : isSandLabBuild() ? "sand-lab" : "sand";
}
