export interface SandDesktopEdgeFailure {
	readonly area: SandDesktopEdgeArea;
	readonly leg: SandDesktopEdgeLeg;
	readonly errorClass: string;
}

export type SandDesktopEdgeFailureReporter = (failure: SandDesktopEdgeFailure) => void;

const PRE_INSTALL_BUFFER_CAP = 32;

let reporter: SandDesktopEdgeFailureReporter | undefined;
let pendingPreInstall: SandDesktopEdgeFailure[] = [];

export function installDesktopEdgeFailureReporter(
	next: SandDesktopEdgeFailureReporter | undefined,
): void {
	reporter = next;
	const flush = pendingPreInstall;
	pendingPreInstall = [];
	if (next == null) return;
	for (const failure of flush) next(failure);
}

export function errorClassOf(error: unknown): string {
	if (!(error instanceof Error)) return typeof error;
	return error.name.length > 0 ? error.name : "Error";
}

export function reportDesktopEdgeFailure(
	area: SandDesktopEdgeArea,
	leg: SandDesktopEdgeLeg,
	error: unknown,
): void {
	reportDesktopEdgeFailureClass(area, leg, errorClassOf(error));
}

export function reportDesktopEdgeFailureClass(
	area: SandDesktopEdgeArea,
	leg: SandDesktopEdgeLeg,
	errorClass: string,
): void {
	const failure: SandDesktopEdgeFailure = { area, leg, errorClass };
	if (reporter != null) {
		reporter(failure);
		return;
	}
	if (pendingPreInstall.length >= PRE_INSTALL_BUFFER_CAP) return;
	pendingPreInstall.push(failure);
}
