import { homedir } from "node:os";
import { isAbsolute, join, resolve } from "node:path";

import { isPathWithin } from "../shared/node/paths.js";

export const SAND_DATA_ROOT_ENV = "SAND_DATA_ROOT";
export const SAND_PRODUCTION_DATA_DIRNAME = ".grokbot";

// Opt-in per-user data isolation, modeled on VS Code's --user-data-dir: when set
// (the `--user-data-dir` desktop CLI flag or this env), every per-user state root
// moves under one directory so two Sand instances can run against different data
// dirs and one can be a pristine first run. The desktop main process resolves the
// flag/env early, sets Electron `userData`/`sessionData` to this path, and
// re-exports the resolved absolute path to this env so the in-process host code
// below (and a spawned host) compute the sand-data root under it too. Unset by
// default, so the normal ~/.cursor/<variant> layout is unchanged.
export const SAND_USER_DATA_DIR_ENV = "SAND_USER_DATA_DIR";

const SAND_DATA_DIRNAME = "sand-data";

const USER_DATA_DIR_FLAG = "--user-data-dir";

export const SAND_BOX_HOME_DIR = "/home/box";
export const SAND_BOX_DATA_ROOT = `${SAND_BOX_HOME_DIR}/${SAND_DATA_DIRNAME}`;

// Reads the `--user-data-dir` value from a desktop argv, accepting both the
// `--user-data-dir=PATH` and `--user-data-dir PATH` forms (Electron only honors
// the `=` form natively, so we parse it ourselves to support both). Returns the
// raw string, or null when the flag is absent or given without a value.
function readUserDataDirArg(argv: readonly string[]): string | null {
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		if (arg === USER_DATA_DIR_FLAG) {
			const next = argv[i + 1];
			return next != null && !next.startsWith("--") ? next : null;
		}
		const prefix = `${USER_DATA_DIR_FLAG}=`;
		if (arg.startsWith(prefix)) return arg.slice(prefix.length);
	}
	return null;
}

export function resolveSandUserDataDir(
	argv: readonly string[] = [],
	env: NodeJS.ProcessEnv = process.env,
	cwd: string = process.cwd(),
): string | null {
	const raw = readUserDataDirArg(argv) ?? env[SAND_USER_DATA_DIR_ENV];
	const trimmed = raw?.trim();
	if (trimmed == null || trimmed.length === 0) return null;
	return isAbsolute(trimmed) ? trimmed : resolve(cwd, trimmed);
}

import { getSandVariant } from "../shared/node/sand-variant.js";

export { type SandVariant } from "../shared/node/sand-variant.js";

export function getSandProductionRootDir(homeDir = homedir()): string {
	return join(homeDir, SAND_PRODUCTION_DATA_DIRNAME);
}

export function getLegacySandProductionRootDir(homeDir = homedir()): string {
	return join(homeDir, ".cursor", "sand");
}

export function resolveSandDataRootOverride(env: NodeJS.ProcessEnv = process.env): string | null {
	const override = env[SAND_DATA_ROOT_ENV]?.trim();
	return override != null && override.length > 0 && isAbsolute(override) ? override : null;
}

export function getSandRootDir(homeDir = homedir()): string {
	const override = resolveSandDataRootOverride();
	if (override != null) return override;
	const userDataDir = resolveSandUserDataDir([], process.env);
	if (userDataDir != null) {
		return join(userDataDir, SAND_DATA_DIRNAME);
	}
	const variant = getSandVariant();
	return variant === "sand" ? getSandProductionRootDir(homeDir) : join(homeDir, ".cursor", variant);
}

export function reanchorSandPath(storedPath: string): string {
	const root = getSandRootDir();
	if (isPathWithin(root, storedPath, { isInclusive: true })) return storedPath;
	const match = /(?:[/\\]\.cursor[/\\]sand(?:-[^/\\]+)?|[/\\]\.grokbot)[/\\](.+)$/.exec(storedPath);
	if (match?.[1] == null) return storedPath;
	const segments = match[1].split(/[/\\]+/);
	if (segments.some((segment) => segment === "." || segment === "..")) {
		return storedPath;
	}
	return join(root, ...segments);
}

export function getGatewayDiscoveryPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), "gateway.json");
}

export function getHostLockPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), "host.lock");
}

export function getHostSecretsPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), "host-secrets.json");
}

export function getHostTokenPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), "host-token.json");
}

export function getHostUpgradeMarkerPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), ".sand-host-upgrade.json");
}

export function getHostCrashMarkerPath(homeDir = homedir()): string {
	return join(getSandRootDir(homeDir), ".sand-host-crash.json");
}
