import { delay } from "../../shared/node/async.js";
import {
	scrubbedOnePasswordEnvironment,
	type SandOnePasswordCliInspection,
	type SandOnePasswordCliReadyCandidate,
} from "./onepassword-cli-runtime.js";
import {
	classifyOnePasswordProcessFailure,
	classifyOnePasswordRuntimeFailure,
	createOnePasswordOpExecutor,
} from "./onepassword-op-executor.js";
import {
	OnePasswordProvisioningError,
	unavailableOnePasswordProvisioningSink,
	type OnePasswordAccount,
	type OnePasswordCliRuntime,
	type OnePasswordDesktopProvisioningBridgeOptions,
	type OnePasswordOpExecutor,
	type OnePasswordOpResult,
	type OnePasswordProvisioningReadiness,
	type OnePasswordProvisioningSink,
	type OnePasswordProvisioningSinkReceipt,
	type OnePasswordVault,
} from "./onepassword-provisioning-contract.js";

export {
	OnePasswordProvisioningError,
	unavailableOnePasswordProvisioningSink,
} from "./onepassword-provisioning-contract.js";
export type {
	OnePasswordAccount,
	OnePasswordDesktopProvisioningBridgeOptions,
	OnePasswordOpExecutor,
	OnePasswordProvisioningErrorCode,
	OnePasswordProvisioningReadiness,
	OnePasswordProvisioningSink,
	OnePasswordProvisioningSinkReceipt,
	OnePasswordProvisioningSinkRequest,
	OnePasswordVault,
} from "./onepassword-provisioning-contract.js";

const MINIMUM_SUPPORTED_VERSION = [2, 35, 0] as const;
const MAX_JSON_OUTPUT_BYTES = 1024 * 1024;
const MAX_TOKEN_OUTPUT_BYTES = 16 * 1024;
const READ_TIMEOUT_MS = 30_000;
const AUTHORIZED_TIMEOUT_MS = 180_000;
const SINK_TIMEOUT_MS = 30_000;
const MAX_ACCOUNTS = 50;
const MAX_VAULTS = 1_000;
const MAX_PROVIDER_ID_LENGTH = 256;
const MAX_NAME_LENGTH = 256;
const MAX_EMAIL_LENGTH = 320;
const MAX_URL_LENGTH = 2_048;
const MAX_CONSUMER_REFERENCE_LENGTH = 256;
const MAX_EXPIRATION_SECONDS = 365 * 24 * 60 * 60;
const MIN_EXPIRATION_SECONDS = 60;

function parseVersion(version: string): readonly number[] | null {
	if (!/^\d+\.\d+\.\d+$/.test(version)) return null;
	const parsed = version.split(".").map((part) => Number.parseInt(part, 10));
	return parsed.every((part) => Number.isSafeInteger(part)) ? parsed : null;
}

function versionAtLeast(version: readonly number[], minimum: readonly number[]): boolean {
	for (let index = 0; index < minimum.length; index += 1) {
		const have = version[index] ?? 0;
		const want = minimum[index] ?? 0;
		if (have > want) return true;
		if (have < want) return false;
	}
	return true;
}

function isSupportedCandidate(candidate: SandOnePasswordCliReadyCandidate): boolean {
	const version = parseVersion(candidate.version);
	return version != null && versionAtLeast(version, MINIMUM_SUPPORTED_VERSION);
}

function selectSupportedCandidate(
	inspection: SandOnePasswordCliInspection,
): SandOnePasswordCliReadyCandidate | null {
	const readyCandidates = inspection.candidates.filter(
		(candidate): candidate is SandOnePasswordCliReadyCandidate => candidate.state === "ready",
	);
	if (
		inspection.selected != null &&
		!readyCandidates.some((candidate) => candidate.path === inspection.selected?.path)
	) {
		readyCandidates.unshift(inspection.selected);
	}
	return (
		readyCandidates.find(
			(candidate) => candidate.source === "system" && isSupportedCandidate(candidate),
		) ??
		readyCandidates.find(
			(candidate) => candidate.source === "managed" && isSupportedCandidate(candidate),
		) ??
		null
	);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value != null && !Array.isArray(value);
}

function providerIdentifier(value: unknown, field: string): string {
	if (
		typeof value !== "string" ||
		!/^[A-Za-z0-9_.-]+$/.test(value) ||
		value.length > MAX_PROVIDER_ID_LENGTH
	) {
		throw new OnePasswordProvisioningError("invalid-input", `The ${field} is invalid.`);
	}
	return value;
}

function boundedName(value: unknown, field: string): string {
	const name = typeof value === "string" ? value.trim() : "";
	if (
		name.length === 0 ||
		name.length > MAX_NAME_LENGTH ||
		name.startsWith("-") ||
		/[\u0000-\u001f\u007f]/.test(name)
	) {
		throw new OnePasswordProvisioningError("invalid-input", `The ${field} is invalid.`);
	}
	return name;
}

function boundedMetadata(value: unknown, maximum: number): string | null {
	if (typeof value !== "string") return null;
	const bounded = value.trim();
	return bounded.length > 0 && bounded.length <= maximum ? bounded : null;
}

function safeAccountUrl(value: unknown): string | null {
	const raw = boundedMetadata(value, MAX_URL_LENGTH);
	if (raw == null) return null;
	try {
		const hasScheme = /^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw);
		const url = new URL(hasScheme ? raw : `https://${raw}`);
		return url.protocol === "https:" &&
			url.hostname !== "" &&
			url.username === "" &&
			url.password === ""
			? url.toString()
			: null;
	} catch {
		return null;
	}
}

function parseAccounts(value: unknown): readonly OnePasswordAccount[] {
	if (!Array.isArray(value) || value.length > MAX_ACCOUNTS) {
		throw new OnePasswordProvisioningError(
			"invalid-output",
			"1Password returned an invalid account list.",
		);
	}
	const accounts: OnePasswordAccount[] = [];
	const seen = new Set<string>();
	for (const entry of value) {
		if (!isRecord(entry)) {
			throw new OnePasswordProvisioningError(
				"invalid-output",
				"1Password returned an invalid account list.",
			);
		}
		const accountUuid = boundedMetadata(entry.account_uuid, MAX_PROVIDER_ID_LENGTH);
		const email = boundedMetadata(entry.email, MAX_EMAIL_LENGTH);
		const url = safeAccountUrl(entry.url);
		if (
			accountUuid == null ||
			!/^[A-Za-z0-9_.-]+$/.test(accountUuid) ||
			email == null ||
			url == null ||
			seen.has(accountUuid)
		) {
			throw new OnePasswordProvisioningError(
				"invalid-output",
				"1Password returned an invalid account list.",
			);
		}
		seen.add(accountUuid);
		accounts.push({ accountUuid, email, url });
	}
	return accounts;
}

function parseVaults(value: unknown): readonly OnePasswordVault[] {
	if (!Array.isArray(value) || value.length > MAX_VAULTS) {
		throw new OnePasswordProvisioningError(
			"invalid-output",
			"1Password returned an invalid vault list.",
		);
	}
	const vaults: OnePasswordVault[] = [];
	const seen = new Set<string>();
	for (const entry of value) {
		if (!isRecord(entry)) {
			throw new OnePasswordProvisioningError(
				"invalid-output",
				"1Password returned an invalid vault list.",
			);
		}
		const vaultId = boundedMetadata(entry.id, MAX_PROVIDER_ID_LENGTH);
		const vaultName = boundedMetadata(entry.name, MAX_NAME_LENGTH);
		if (
			vaultId == null ||
			!/^[A-Za-z0-9_.-]+$/.test(vaultId) ||
			vaultName == null ||
			seen.has(vaultId)
		) {
			throw new OnePasswordProvisioningError(
				"invalid-output",
				"1Password returned an invalid vault list.",
			);
		}
		seen.add(vaultId);
		vaults.push({ vaultId, vaultName });
	}
	return vaults;
}

function parseCreatedVault(value: unknown): OnePasswordVault {
	if (!isRecord(value)) {
		throw new OnePasswordProvisioningError(
			"invalid-output",
			"1Password did not return the created vault.",
		);
	}
	const vaultId = boundedMetadata(value.id, MAX_PROVIDER_ID_LENGTH);
	const vaultName = boundedMetadata(value.name, MAX_NAME_LENGTH);
	if (vaultId == null || !/^[A-Za-z0-9_.-]+$/.test(vaultId) || vaultName == null) {
		throw new OnePasswordProvisioningError(
			"invalid-output",
			"1Password did not return the created vault.",
		);
	}
	return { vaultId, vaultName };
}

function expirationSeconds(value: unknown): number {
	if (
		typeof value !== "number" ||
		!Number.isSafeInteger(value) ||
		value < MIN_EXPIRATION_SECONDS ||
		value > MAX_EXPIRATION_SECONDS
	) {
		throw new OnePasswordProvisioningError(
			"invalid-input",
			"The provisioning policy returned an invalid expiration duration.",
		);
	}
	return value;
}

function validToken(stdout: string): string {
	const token = stdout.trim();
	if (
		token.length === 0 ||
		token.length > MAX_TOKEN_OUTPUT_BYTES ||
		!/^ops_[A-Za-z0-9_-]+$/.test(token)
	) {
		throw new OnePasswordProvisioningError(
			"invalid-output",
			"1Password did not return a valid service-account credential.",
		);
	}
	return token;
}

export class OnePasswordDesktopProvisioningBridge {
	private readonly runtime: OnePasswordCliRuntime;
	private readonly sink: OnePasswordProvisioningSink;
	private readonly executor: OnePasswordOpExecutor;
	private readonly prepareManagedCli: boolean;
	private mutationInProgress = false;
	private deliveryIndeterminate = false;

	constructor(options: OnePasswordDesktopProvisioningBridgeOptions) {
		this.runtime = options.runtime;
		this.sink = options.sink ?? unavailableOnePasswordProvisioningSink;
		this.executor = options.executor ?? createOnePasswordOpExecutor();
		this.prepareManagedCli = options.prepareManagedCli ?? true;
	}

	async inspectReadiness(signal: AbortSignal): Promise<OnePasswordProvisioningReadiness> {
		const inspection = await this.runtime.inspect(signal).catch((error) => {
			throw classifyOnePasswordRuntimeFailure(error);
		});
		if (!inspection.platformSupported) return { state: "unsupported-platform" };
		const selected = selectSupportedCandidate(inspection);
		if (selected != null) {
			return {
				state: "ready",
				source: selected.source,
				path: selected.path,
				version: selected.version,
			};
		}
		const unsupported = inspection.selected;
		if (unsupported == null) return { state: "missing-cli" };
		return {
			state: "unsupported-version",
			version: unsupported.version,
		};
	}

	async listAccounts(signal: AbortSignal): Promise<readonly OnePasswordAccount[]> {
		return parseAccounts(
			await this.runJson(["account", "list", "--format=json"], READ_TIMEOUT_MS, signal),
		);
	}

	async listVaults(
		request: { readonly accountUuid: string },
		signal: AbortSignal,
	): Promise<readonly OnePasswordVault[]> {
		const accountUuid = providerIdentifier(request.accountUuid, "1Password account identifier");
		return parseVaults(
			await this.runJson(
				["vault", "list", "--account", accountUuid, "--format=json"],
				READ_TIMEOUT_MS,
				signal,
			),
		);
	}

	async findVault(
		request: { readonly accountUuid: string; readonly vaultName: string },
		signal: AbortSignal,
	): Promise<OnePasswordVault | null> {
		const wanted = boundedName(request.vaultName, "vault name");
		const matches = (await this.listVaults(request, signal)).filter(
			(vault) => vault.vaultName === wanted,
		);
		if (matches.length > 1) {
			throw new OnePasswordProvisioningError(
				"conflict",
				"More than one 1Password vault has the requested name.",
			);
		}
		return matches[0] ?? null;
	}

	async createVault(
		request: { readonly accountUuid: string; readonly vaultName: string },
		signal: AbortSignal,
	): Promise<OnePasswordVault> {
		this.assertSinkAvailable();
		const accountUuid = providerIdentifier(request.accountUuid, "1Password account identifier");
		const vaultName = boundedName(request.vaultName, "vault name");
		return await this.runMutation(signal, async (mutationSignal) => {
			return parseCreatedVault(
				await this.runJson(
					["vault", "create", vaultName, "--account", accountUuid, "--format=json"],
					AUTHORIZED_TIMEOUT_MS,
					mutationSignal,
				),
			);
		});
	}

	async mintAndDeliver(
		request: {
			readonly accountUuid: string;
			readonly vaultId: string;
			readonly serviceAccountName: string;
			readonly expiresInSeconds: number;
		},
		signal: AbortSignal,
	): Promise<{
		readonly consumerReference: string;
		readonly expiresInSeconds: number;
	}> {
		this.assertSinkAvailable();
		const accountUuid = providerIdentifier(request.accountUuid, "1Password account identifier");
		const vaultId = providerIdentifier(request.vaultId, "1Password vault identifier");
		const serviceAccountName = boundedName(request.serviceAccountName, "service-account name");
		const expiresInSeconds = expirationSeconds(request.expiresInSeconds);

		return await this.runMutation(signal, async (mutationSignal) => {
			const account = (await this.listAccounts(mutationSignal)).find(
				(candidate) => candidate.accountUuid === accountUuid,
			);
			if (account == null) {
				throw new OnePasswordProvisioningError(
					"invalid-input",
					"The selected 1Password account is unavailable.",
				);
			}
			const vault = (await this.listVaults({ accountUuid }, mutationSignal)).find(
				(candidate) => candidate.vaultId === vaultId,
			);
			if (vault == null) {
				throw new OnePasswordProvisioningError(
					"permission",
					"The selected 1Password vault is unavailable to this account.",
				);
			}
			const result = await this.runOp(
				[
					"service-account",
					"create",
					serviceAccountName,
					"--account",
					accountUuid,
					"--vault",
					`${vaultId}:read_items`,
					"--expires-in",
					`${expiresInSeconds}s`,
					"--raw",
				],
				AUTHORIZED_TIMEOUT_MS,
				MAX_TOKEN_OUTPUT_BYTES,
				mutationSignal,
			);
			const token = validToken(result.stdout);

			// Once op returned a credential, user cancellation no longer discards it:
			// delivery gets its own short deadline so an accepted provider credential
			// cannot become an orphan merely because the UI was closed.
			const sinkController = new AbortController();
			const deadlineController = new AbortController();
			let receipt: OnePasswordProvisioningSinkReceipt;
			try {
				const sinkPromise = this.sink.accept(
					{
						accountUuid,
						accountUrl: account.url,
						vaultId,
						vaultName: vault.vaultName,
						serviceAccountName,
						expiresInSeconds,
						token,
					},
					sinkController.signal,
				);
				const deadlinePromise = delay(SINK_TIMEOUT_MS, deadlineController.signal).then(async () => {
					if (deadlineController.signal.aborted) return await sinkPromise;
					sinkController.abort(new DOMException("Provisioning sink timed out", "TimeoutError"));
					throw new DOMException("Provisioning sink timed out", "TimeoutError");
				});
				receipt = await Promise.race([sinkPromise, deadlinePromise]);
			} catch {
				this.deliveryIndeterminate = true;
				throw new OnePasswordProvisioningError(
					"delivery-indeterminate",
					"The credential delivery outcome is unknown and must be reconciled before provisioning again.",
				);
			} finally {
				deadlineController.abort();
			}
			const consumerReference = isRecord(receipt)
				? boundedMetadata(receipt.consumerReference, MAX_CONSUMER_REFERENCE_LENGTH)
				: null;
			if (consumerReference == null) {
				this.deliveryIndeterminate = true;
				throw new OnePasswordProvisioningError(
					"delivery-indeterminate",
					"The credential delivery outcome is unknown and must be reconciled before provisioning again.",
				);
			}
			return { consumerReference, expiresInSeconds };
		});
	}

	private assertSinkAvailable(): void {
		if (this.sink.availability !== "available") {
			throw new OnePasswordProvisioningError(
				"sink-unavailable",
				"1Password provisioning is unavailable until a credential consumer is configured.",
			);
		}
	}

	private async runMutation<T>(
		callerSignal: AbortSignal,
		operation: (signal: AbortSignal) => Promise<T>,
	): Promise<T> {
		if (this.deliveryIndeterminate) {
			throw new OnePasswordProvisioningError(
				"delivery-indeterminate",
				"The previous credential delivery must be reconciled before provisioning again.",
			);
		}
		if (this.mutationInProgress) {
			throw new OnePasswordProvisioningError(
				"busy",
				"A 1Password provisioning operation is already running.",
			);
		}
		this.mutationInProgress = true;
		try {
			if (callerSignal.aborted) {
				throw new OnePasswordProvisioningError(
					"cancelled",
					"The 1Password operation was canceled.",
				);
			}
			return await operation(callerSignal);
		} finally {
			this.mutationInProgress = false;
		}
	}

	private async runJson(
		args: readonly string[],
		timeoutMs: number,
		signal: AbortSignal,
	): Promise<unknown> {
		const result = await this.runOp(args, timeoutMs, MAX_JSON_OUTPUT_BYTES, signal);
		try {
			const parsed: unknown = JSON.parse(result.stdout);
			return parsed;
		} catch {
			throw new OnePasswordProvisioningError(
				"invalid-output",
				"1Password returned malformed JSON.",
			);
		}
	}

	private async runOp(
		args: readonly string[],
		timeoutMs: number,
		maxBufferBytes: number,
		signal: AbortSignal,
	): Promise<OnePasswordOpResult> {
		const opPath = await this.resolveSupportedPath(signal);
		let launcherPath: string;
		try {
			launcherPath = await this.runtime.resolveVerifiedLauncherPath(signal);
		} catch (error) {
			throw classifyOnePasswordRuntimeFailure(error);
		}
		try {
			return await this.executor(launcherPath, [opPath, ...args], {
				signal,
				timeoutMs,
				maxBufferBytes,
				env: scrubbedOnePasswordEnvironment(),
			});
		} catch (error) {
			throw classifyOnePasswordProcessFailure(error);
		}
	}

	private async resolveSupportedPath(signal: AbortSignal): Promise<string> {
		let readiness = await this.inspectReadiness(signal);
		if (readiness.state === "ready") return readiness.path;
		if (
			(readiness.state === "missing-cli" || readiness.state === "unsupported-version") &&
			this.prepareManagedCli &&
			!signal.aborted
		) {
			try {
				await this.runtime.prepareManaged(signal);
			} catch (error) {
				throw classifyOnePasswordRuntimeFailure(error);
			}
			readiness = await this.inspectReadiness(signal);
			if (readiness.state === "ready") return readiness.path;
		}
		if (readiness.state === "unsupported-platform") {
			throw new OnePasswordProvisioningError(
				"unsupported-platform",
				"1Password desktop provisioning is supported on macOS only.",
			);
		}
		if (readiness.state === "unsupported-version") {
			throw new OnePasswordProvisioningError(
				"unsupported-version",
				"The detected 1Password CLI does not support expiring service accounts.",
			);
		}
		throw new OnePasswordProvisioningError("missing-cli", "No verified 1Password CLI is ready.");
	}
}
