/**
 * Thrown by a failed {@link invariant}: a must-never-happen construction or
 * wiring claim was false, so continuing would corrupt. The crash-class
 * machinery owns what follows; a best-effort operation that failed records a
 * classified diagnostic and continues instead of reaching for this.
 */
export class SandInvariantViolation extends Error {
	constructor(message: string) {
		super(message);
		this.name = "SandInvariantViolation";
	}
}

/**
 * The bounded fields a failed invariant reports before throwing: the
 * violation name and the top application frame — never the message, whose
 * interpolated values must not ride telemetry.
 */
export interface InvariantReport {
	readonly name: string;
	readonly frame: string | null;
}

export type InvariantReporter = (report: InvariantReport) => void;

let installedReporter: InvariantReporter | null = null;

/**
 * Installs the process-owned failure reporter once and returns its
 * uninstall handle. Without one, invariants throw only.
 */
export function installInvariantReporter(reporter: InvariantReporter): () => void {
	invariant(
		installedReporter === null,
		"installInvariantReporter: a reporter is already installed",
	);
	installedReporter = reporter;
	return () => {
		if (installedReporter === reporter) installedReporter = null;
	};
}

declare const __SAND_STRIP_INVARIANT_MESSAGES__: boolean | undefined;

const STRIPPED_MESSAGE =
	"Invariant violation (message stripped in packaged builds; the stack identifies the site)";

function messagesStripped(): boolean {
	return (
		typeof __SAND_STRIP_INVARIANT_MESSAGES__ === "boolean" && __SAND_STRIP_INVARIANT_MESSAGES__
	);
}

const FRAME_LINE = /^at /;
const OWN_FRAME = /^at (?:new SandInvariantViolation\b|invariant\b|installInvariantReporter\b)/;

// Parse only the exact V8 error header so hostile message text cannot forge a frame.
function topApplicationFrame(violation: SandInvariantViolation): string | null {
	const stack = violation.stack;
	if (stack == null || !stack.startsWith(headerOf(violation))) return null;
	for (const raw of stack.slice(headerOf(violation).length).split("\n")) {
		const frame = raw.trim();
		if (!FRAME_LINE.test(frame) || OWN_FRAME.test(frame)) continue;
		return frame;
	}
	return null;
}

function headerOf(violation: SandInvariantViolation): string {
	return violation.message === "" ? violation.name : `${violation.name}: ${violation.message}`;
}

/**
 * Reports and throws a failed invariant while narrowing successful values.
 * Packaged builds strip message text; development builds retain it and
 * evaluate lazy messages only on failure.
 */
export function invariant(condition: unknown, message: string | (() => string)): asserts condition {
	if (condition) return;
	let violationMessage: string;
	if (messagesStripped()) {
		violationMessage = STRIPPED_MESSAGE;
	} else if (typeof message === "function") {
		violationMessage = message();
	} else {
		violationMessage = message;
	}
	const violation = new SandInvariantViolation(violationMessage);
	installedReporter?.({ name: violation.name, frame: topApplicationFrame(violation) });
	throw violation;
}
